def utc_now() -> str:
    return (
        datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
    )


def default_data_dir() -> Path:
    portable = os.environ.get("UNIVERSE_DATA_DIR")
    if portable:
        return Path(portable).expanduser()
    local_app_data = os.environ.get("LOCALAPPDATA")
    if local_app_data:
        return Path(local_app_data) / "Universe"
    return Path.home() / ".local" / "share" / "universe"


def default_database_path() -> Path:
    override = os.environ.get("UNIVERSE_DATABASE")
    if override:
        return Path(override).expanduser()
    return default_data_dir() / "universe.sqlite3"


def default_state_path() -> Path:
    override = os.environ.get("UNIVERSE_STATE_FILE")
    if override:
        return Path(override).expanduser()
    return default_data_dir() / "server.json"




def provider_ref_from_model_ref(model_ref: Any) -> str:
    """Derive an explicit provider dimension from a canonical model reference."""

    normalized = _required_text(model_ref, "model_ref")
    match = re.fullmatch(
        r"provider://([A-Za-z0-9][A-Za-z0-9._-]{0,127})/model/.+",
        normalized,
    )
    return match.group(1).upper() if match else "UNKNOWN"


def resolve_universe_mode_intent(value: Any) -> str:
    intent = _required_text(value, "mode_intent").upper()
    try:
        return CONDUCTOR_MODE_INTENTS[intent]
    except KeyError as error:
        raise UniverseError(
            "MODE_INTENT_UNSUPPORTED",
            "Universe accepts only Conductor Mode intent",
        ) from error


def load_universe_mode_registry(path: Path) -> dict[str, Any]:
    try:
        registry = json.loads(path.expanduser().read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise UniverseError(
            "UNIVERSE_MODE_REGISTRY_UNAVAILABLE",
            str(error),
        ) from error
    if not isinstance(registry, dict):
        raise UniverseError(
            "UNIVERSE_MODE_REGISTRY_INVALID",
            "Universe Mode Registry must be an object",
        )
    if (
        registry.get("owner") != "universe"
        or registry.get("policy") != "MASTER_MANAGED"
        or registry.get("root_mode") != MASTER_MODE
    ):
        raise UniverseError(
            "UNIVERSE_MODE_CONTRACT_MISMATCH",
            "Universe Mode Registry owner, policy, and root Mode must remain canonical",
        )
    modes = registry.get("modes")
    if not isinstance(modes, dict):
        raise UniverseError(
            "UNIVERSE_MODE_REGISTRY_INVALID",
            "Universe Mode Registry modes must be an object",
        )
    expected = {
        MASTER_MODE: {
            "role": MASTER_MODE,
            "scope": "architecture/governance",
            "mode_profile": "GOVERNANCE_ONLY",
        },
        CONDUCTOR_MODE: {
            "role": CONDUCTOR_ROLE,
            "scope": CONDUCTOR_SCOPE,
            "mode_profile": CONDUCTOR_MODE_PROFILE,
        },
    }
    unexpected = sorted(set(modes) - set(expected))
    missing = sorted(set(expected) - set(modes))
    if unexpected or missing:
        raise UniverseError(
            "UNIVERSE_MODE_CONTRACT_MISMATCH",
            "Universe Mode Registry entry does not match the required contract: "
            f"{(unexpected or missing)[0]}",
        )
    for mode, definition in expected.items():
        if modes.get(mode) != definition:
            raise UniverseError(
                "UNIVERSE_MODE_CONTRACT_MISMATCH",
                f"Universe Mode Registry entry does not match the required contract: {mode}",
            )
    return registry


def universe_mode_contract(registry: dict[str, Any]) -> dict[str, Any]:
    definition = registry["modes"][CONDUCTOR_MODE]
    return {
        "schema": UNIVERSE_MODE_CONTRACT_SCHEMA,
        "status": "ACTIVE",
        "mode": CONDUCTOR_MODE,
        "role": definition["role"],
        "scope": definition["scope"],
        "mode_profile": definition["mode_profile"],
        "registry_revision": registry.get("revision", "UNKNOWN"),
    }


def unknown_universe_mode_contract() -> dict[str, Any]:
    return {
        "schema": UNIVERSE_MODE_CONTRACT_SCHEMA,
        "status": "UNKNOWN",
        "mode": CONDUCTOR_MODE,
        "role": CONDUCTOR_ROLE,
        "scope": CONDUCTOR_SCOPE,
        "mode_profile": CONDUCTOR_MODE_PROFILE,
        "registry_revision": "UNKNOWN",
    }


def require_release_lifecycle_mode(mode: Any) -> None:
    if _required_text(mode, "mode").upper() != MASTER_MODE:
        raise UniverseError(
            "MASTER_MODE_REQUIRED",
            "Release database installation and update require MASTER Mode",
            HTTPStatus.CONFLICT,
        )


















def _project_id(value: Any) -> str:
    project_id = _required_text(value, "project_id")
    if not PROJECT_ID_PATTERN.fullmatch(project_id):
        raise UniverseError(
            "PROJECT_ID_INVALID",
            "project_id must use letters, digits, dot, underscore, or hyphen",
        )
    return project_id


def normalize_project_attachment(
    value: Any = None,
    *,
    default_membership: str = "DETACHED",
    install_mode: Any = None,
) -> dict[str, str]:
    """Return the versioned attachment record without changing project identity."""

    if value is None:
        raw: dict[str, Any] = {}
    elif isinstance(value, dict):
        raw = dict(value)
    else:
        raise UniverseError(
            "PROJECT_ATTACHMENT_INVALID",
            "attachment must be an object",
        )

    unknown = set(raw) - PROJECT_ATTACHMENT_FIELDS
    if unknown:
        raise UniverseError(
            "PROJECT_ATTACHMENT_INVALID",
            f"attachment contains unsupported fields: {', '.join(sorted(unknown))}",
        )

    schema = raw.get("schema", PROJECT_ATTACHMENT_SCHEMA)
    if schema != PROJECT_ATTACHMENT_SCHEMA:
        raise UniverseError(
            "PROJECT_ATTACHMENT_SCHEMA_INVALID",
            f"attachment schema must be {PROJECT_ATTACHMENT_SCHEMA}",
        )

    default_membership = _required_text(
        default_membership, "default_membership"
    ).upper()
    if default_membership not in PROJECT_UNIVERSE_MEMBERSHIPS:
        raise UniverseError(
            "PROJECT_ATTACHMENT_VALUE_INVALID",
            f"unsupported default_membership: {default_membership}",
        )

    defaults = {
        "install_origin": "PROJECT_STANDALONE",
        "universe_membership": default_membership,
        "runtime_host": "PROJECT_LOCAL",
    }

    if install_mode is not None:
        normalized_mode = _required_text(install_mode, "install_mode").upper()
        if normalized_mode not in {"PROJECT_STANDALONE", "UNIVERSE_ATTACHED"}:
            raise UniverseError(
                "PROJECT_INSTALL_MODE_INVALID",
                "install_mode must be PROJECT_STANDALONE or UNIVERSE_ATTACHED",
            )
        # The legacy flag describes the connection posture, not historical
        # origin. Keep origin conservative and only map the live relationship.
        if normalized_mode == "UNIVERSE_ATTACHED":
            defaults["universe_membership"] = "LINKED"

    normalized: dict[str, str] = {"schema": PROJECT_ATTACHMENT_SCHEMA}
    for field, allowed in (
        ("install_origin", PROJECT_INSTALL_ORIGINS),
        ("universe_membership", PROJECT_UNIVERSE_MEMBERSHIPS),
        ("runtime_host", PROJECT_RUNTIME_HOSTS),
    ):
        candidate = raw.get(field, defaults[field])
        candidate = _required_text(candidate, f"attachment.{field}").upper()
        if candidate not in allowed:
            raise UniverseError(
                "PROJECT_ATTACHMENT_VALUE_INVALID",
                f"unsupported attachment.{field}: {candidate}",
            )
        normalized[field] = candidate
    return normalized


def _event_type(value: Any) -> str:
    event_type = _required_text(value, "event_type").upper()
    if not EVENT_TYPE_PATTERN.fullmatch(event_type):
        raise UniverseError(
            "EVENT_TYPE_INVALID",
            "event_type must be an uppercase identifier",
        )
    return event_type


def _identifier(value: Any, field: str) -> str:
    identifier = _required_text(value, field)
    if not PROJECT_ID_PATTERN.fullmatch(identifier):
        raise UniverseError(
            "IDENTIFIER_INVALID",
            f"{field} must use letters, digits, dot, underscore, or hyphen",
        )
    return identifier


def _exact_object_fields(
    value: Any,
    *,
    field: str,
    required: frozenset[str],
    optional: frozenset[str] = frozenset(),
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise UniverseError("REQUEST_INVALID", f"{field} must be an object")
    missing = required - set(value)
    if missing:
        raise UniverseError(
            "REQUEST_INVALID",
            f"{field} is missing: {', '.join(sorted(missing))}",
        )
    unknown = set(value) - required - optional
    if unknown:
        raise UniverseError(
            "REQUEST_INVALID",
            f"{field} contains unsupported fields: {', '.join(sorted(unknown))}",
        )
    return dict(value)


def _canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )


def _json_sha256(value: Any) -> str:
    return hashlib.sha256(_canonical_json(value).encode("utf-8")).hexdigest()


def _canonical_provider_source_path(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    return os.path.normcase(os.path.normpath(str(Path(text).resolve())))


def _provider_source_key(value: Mapping[str, Any]) -> str:
    identity = {
        "provider": str(value.get("provider") or "UNKNOWN").upper(),
        "provider_session_id": str(value.get("provider_session_id") or ""),
        "source_path": _canonical_provider_source_path(value.get("source_path")),
    }
    return "provider_source_" + _json_sha256(identity)[:24]




def _unwrap_anchor_snapshot(payload: Any) -> dict[str, Any]:
    if not isinstance(payload, Mapping):
        return {}
    inner = payload.get("snapshot")
    if isinstance(inner, Mapping):
        merged = dict(payload)
        merged.update(inner)
        return merged
    return dict(payload)


def _session_store_digest(session_id: str) -> str:
    return hashlib.sha256(str(session_id).encode("utf-8")).hexdigest()[:24]


def _vendor_identity_from_observer(observer_ref: str) -> tuple[str, str] | None:
    raw = str(observer_ref or "").strip()
    lowered = raw.lower()
    prefixed = (
        ("grok-acp:", "GROK"),
        ("grok-cli:", "GROK"),
        ("claude-code:", "CLAUDE"),
        ("codex-app-server:", "CODEX"),
        ("codex-app:", "CODEX"),
        ("codex:", "CODEX"),
        ("cli-terminal:", "CODEX"),
    )
    for prefix, provider in prefixed:
        if lowered.startswith(prefix):
            vendor_id = raw[len(prefix) :].strip()
            return (provider, vendor_id) if vendor_id else None
    return None


def _verified_provider_identity_index(
    sources: Iterable[Mapping[str, Any]],
) -> tuple[
    dict[tuple[str, str], Mapping[str, Any]],
    dict[str, list[tuple[str, str]]],
]:
    provider_identities: dict[tuple[str, str], Mapping[str, Any]] = {}
    exact_identities: dict[str, list[tuple[str, str]]] = {}
    for source in sources:
        provider = str(source.get("provider") or "").upper()
        provider_session_id = str(source.get("provider_session_id") or "").strip()
        if (
            source.get("identity_state") != "VERIFIED"
            or str(source.get("session_kind") or "CHAT").upper() == "WORKER"
            or provider not in {"CODEX", "CLAUDE", "GROK"}
            or not provider_session_id
        ):
            continue
        identity = (provider, provider_session_id)
        provider_identities.setdefault(identity, source)
        exact_identities.setdefault(provider_session_id, []).append(identity)
    return provider_identities, exact_identities


def _resolve_verified_provider_identity(
    observer_ref: Any,
    provider_identities: Mapping[tuple[str, str], Mapping[str, Any]],
    exact_identities: Mapping[str, list[tuple[str, str]]],
) -> tuple[str, str] | None:
    raw = str(observer_ref or "").strip()
    if not raw or raw.upper() in {"UNKNOWN", "UNASSIGNED", "NONE"}:
        return None
    prefixed = (
        ("claude-code:", "CLAUDE"),
        ("grok-acp:", "GROK"),
        ("grok-cli:", "GROK"),
        ("codex-app-server:", "CODEX"),
        ("codex-app:", "CODEX"),
        ("codex:", "CODEX"),
    )
    lowered = raw.lower()
    for prefix, provider in prefixed:
        if lowered.startswith(prefix):
            identity = (provider, raw[len(prefix) :].strip())
            return identity if identity in provider_identities else None
    exact = exact_identities.get(raw) or []
    return exact[0] if len(exact) == 1 else None


def _vendor_chat_key(provider: str, provider_session_id: str) -> str:
    identity = {
        "provider": str(provider or "UNKNOWN").upper(),
        "provider_session_id": str(provider_session_id or ""),
        "source_path": "",
    }
    return "provider_chat_" + _provider_source_key(identity).removeprefix(
        "provider_source_"
    )


def _read_project_runtime_anchors(
    store: Path,
) -> tuple[dict[str, dict[str, Any]], dict[str, dict[str, Any]]]:
    current_by_mode: dict[str, dict[str, Any]] = {}
    beyond_by_anchor: dict[str, dict[str, Any]] = {}
    if not store.is_file():
        return current_by_mode, beyond_by_anchor
    connection: sqlite3.Connection | None = None
    try:
        connection = sqlite3.connect(
            f"file:{store.resolve().as_posix()}?mode=ro",
            uri=True,
        )
        connection.row_factory = sqlite3.Row
        tables = {
            str(row[0])
            for row in connection.execute(
                "SELECT name FROM sqlite_master WHERE type = 'table'"
            ).fetchall()
        }
        if "mode_current_anchor" in tables:
            for row in connection.execute(
                """
                SELECT mode, frame_id, anchor_id, state, observed_at, snapshot_json
                FROM mode_current_anchor
                """
            ):
                try:
                    payload = json.loads(str(row["snapshot_json"] or ""))
                except (TypeError, ValueError, json.JSONDecodeError):
                    payload = {}
                inner = _unwrap_anchor_snapshot(payload)
                mode = str(row["mode"] or "").strip().upper()
                if not mode:
                    continue
                current_by_mode[mode] = {
                    "mode": mode,
                    "frame_id": str(row["frame_id"] or "current"),
                    "anchor_id": str(row["anchor_id"] or ""),
                    "state": str(
                        row["state"] or inner.get("state") or "CURRENT"
                    ).upper(),
                    "observed_at": str(row["observed_at"] or ""),
                    "observer_session_ref": str(
                        inner.get("observer_session_ref") or ""
                    ).strip(),
                    "session_id": str(inner.get("session_id") or "").strip(),
                }
        if "beyond_anchor" in tables:
            for row in connection.execute(
                """
                SELECT mode, frame_id, anchor_id, observed_at, retired_at,
                       snapshot_json
                FROM beyond_anchor
                """
            ):
                try:
                    payload = json.loads(str(row["snapshot_json"] or ""))
                except (TypeError, ValueError, json.JSONDecodeError):
                    payload = {}
                inner = _unwrap_anchor_snapshot(payload)
                coordinates = inner.get("coordinates")
                if not isinstance(coordinates, Mapping):
                    coordinates = {}
                mode = str(
                    row["mode"] or coordinates.get("mode") or ""
                ).strip().upper()
                anchor_id = str(row["anchor_id"] or "").strip()
                if not anchor_id:
                    continue
                beyond_by_anchor[anchor_id] = {
                    "mode": mode,
                    "frame_id": str(row["frame_id"] or "current"),
                    "anchor_id": anchor_id,
                    "observed_at": str(row["observed_at"] or ""),
                    "retired_at": str(row["retired_at"] or ""),
                    "observer_session_ref": str(
                        inner.get("observer_session_ref") or ""
                    ).strip(),
                    "session_id": str(inner.get("session_id") or "").strip(),
                    "state": str(inner.get("state") or "UNKNOWN").upper(),
                }
    except (OSError, sqlite3.Error):
        return current_by_mode, beyond_by_anchor
    finally:
        if connection is not None:
            connection.close()
    return current_by_mode, beyond_by_anchor


def _read_session_store_rows(session_dir: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if not session_dir.is_dir():
        return rows
    for path in sorted(session_dir.glob("session-*.sqlite3")):
        if path.name.endswith(("-wal", "-shm")):
            continue
        digest = path.stem.removeprefix("session-")
        connection: sqlite3.Connection | None = None
        try:
            connection = sqlite3.connect(
                f"file:{path.resolve().as_posix()}?mode=ro",
                uri=True,
            )
            connection.row_factory = sqlite3.Row
            tables = {
                str(row[0])
                for row in connection.execute(
                    "SELECT name FROM sqlite_master WHERE type = 'table'"
                ).fetchall()
            }
            if "anchor_snapshot" not in tables:
                rows.append({"digest": digest, "present": True})
                continue
            row = connection.execute(
                "SELECT * FROM anchor_snapshot WHERE singleton = 1"
            ).fetchone()
            if row is None:
                rows.append({"digest": digest, "present": True})
                continue
            try:
                payload = json.loads(str(row["snapshot_json"] or ""))
            except (TypeError, ValueError, json.JSONDecodeError):
                payload = {}
            inner = _unwrap_anchor_snapshot(payload)
            coordinates = inner.get("coordinates")
            if not isinstance(coordinates, Mapping):
                coordinates = {}
            rows.append(
                {
                    "digest": digest,
                    "present": True,
                    "anchor_id": str(row["anchor_id"] or "").strip(),
                    "state": str(
                        row["state"] or inner.get("state") or ""
                    ).upper(),
                    "observed_at": str(row["observed_at"] or ""),
                    "session_id": str(inner.get("session_id") or "").strip(),
                    "observer_session_ref": str(
                        inner.get("observer_session_ref") or ""
                    ).strip(),
                    "mode": str(coordinates.get("mode") or "").strip().upper(),
                }
            )
        except (OSError, sqlite3.Error):
            continue
        finally:
            if connection is not None:
                connection.close()
    return rows


def _chat_key_for_observer(observer_ref: str) -> tuple[str, str | None]:
    identity = _vendor_identity_from_observer(observer_ref)
    if identity is None:
        return "UNKNOWN", None
    return identity[0], _vendor_chat_key(identity[0], identity[1])


PTY_BINDING_UNBOUND: dict[str, Any] = {
    "status": "UNBOUND",
    "terminal_id": None,
    "pty_state": None,
    "pid": None,
    "provider": None,
}


def _public_pty_binding(binding: Mapping[str, Any] | None) -> dict[str, Any]:
    """Render the PTY side of one session record.

    Liveness and binding are observations about a terminal.  They never imply
    Authority, Execution Assignment, or Mode Current Anchor currentness, so
    this projection stays separate from the currentness fields.
    """

    if not isinstance(binding, Mapping):
        return dict(PTY_BINDING_UNBOUND)
    return {
        "status": str(binding.get("status") or "UNBOUND").upper(),
        "terminal_id": str(binding.get("terminal_id") or "") or None,
        "pty_state": str(binding.get("pty_state") or "") or None,
        "pid": binding.get("pid"),
        "provider": str(binding.get("provider") or "") or None,
        "backend_owner": str(binding.get("backend_owner") or "") or None,
        "reconnection_host_id": str(binding.get("reconnection_host_id") or "") or None,
    }


def _public_anchor_session(
    *,
    project_id: str,
    mode: str,
    session_id: str,
    provider: str,
    session_anchor_ref: str,
    current_anchor_ref: str,
    origin_anchor_ref: str,
    temporality: str,
    currentness: str,
    currentness_source: str,
    state: str,
    last_seen_at: str,
    chat_key: str | None,
    store_present: bool,
    observer_session_ref: str = "",
    pty_binding: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    universe_id = session_id if str(session_id).startswith("UNIVERSE-") else None
    observer = str(observer_session_ref or "").strip()
    return {
        "schema": "universe.project-anchor-session.v1",
        "project_id": project_id,
        "node": project_id,
        "mode": mode,
        "session_id": session_id,
        "universe_session_id": universe_id,
        "alias": session_id if universe_id else f"{project_id} {mode}",
        "provider": provider,
        "observer_session_ref": observer,
        "session_anchor_ref": session_anchor_ref,
        "current_anchor_ref": current_anchor_ref,
        "origin_anchor_ref": origin_anchor_ref,
        "temporality": temporality,
        "currentness": currentness,
        "observer_currentness": currentness,
        "currentness_source": currentness_source,
        "state": state,
        "active_ing": is_active_ing_state(state),
        "last_seen_at": last_seen_at or None,
        "chat_key": chat_key,
        "store_present": store_present,
        "pty_binding": _public_pty_binding(pty_binding),
    }


def _public_provider_source(value: Mapping[str, Any]) -> dict[str, Any]:
    source = dict(value)
    source["source_key"] = _provider_source_key(source)
    source["provider_session_id"] = "REDACTED"
    source["source_path"] = "REDACTED"
    source["file_identity"] = None
    return source


def _public_provider_activity(value: Mapping[str, Any]) -> dict[str, Any]:
    allowed = (
        "schema",
        "activity_id",
        "source_id",
        "ordinal",
        "event_kind",
        "activity_state",
        "observed_at",
        "activity_digest",
        "active",
        "recorded_at",
    )
    return {key: value.get(key) for key in allowed}


def _write_bytes_atomic(path: Path, content: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.is_file() and path.read_bytes() == content:
        return
    descriptor, temporary_name = tempfile.mkstemp(
        prefix=f".{path.name}.",
        suffix=".tmp",
        dir=path.parent,
    )
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        try:
            path.chmod(0o444)
        except OSError:
            pass
    finally:
        if temporary.exists():
            temporary.unlink()


def _sha256(value: Any, field: str) -> str:
    digest = _required_text(value, field).lower()
    if not SHA256_PATTERN.fullmatch(digest):
        raise UniverseError("SHA256_INVALID", f"{field} must be lowercase SHA-256")
    return digest


def _source_commit(value: Any) -> str:
    commit = _required_text(value, "source.commit").lower()
    if not SOURCE_COMMIT_PATTERN.fullmatch(commit):
        raise UniverseError(
            "SOURCE_COMMIT_INVALID",
            "source.commit must be a lowercase immutable commit digest",
        )
    return commit


def _canonical_project_root(value: Any) -> Path:
    raw = Path(_required_text(value, "project_root")).expanduser()
    try:
        root = raw.resolve(strict=True)
    except OSError as error:
        raise UniverseError("PROJECT_ROOT_UNAVAILABLE", str(error)) from error
    if not root.is_dir():
        raise UniverseError("PROJECT_ROOT_INVALID", "project_root must be a directory")
    return root


def _relative_project_path(project_root: Path, value: Any, field: str) -> str:
    text = _required_text(value, field).replace("\\", "/")
    path = Path(text)
    if path.is_absolute() or ".." in path.parts:
        raise UniverseError(
            "PROJECT_REF_INVALID",
            f"{field} must remain relative to project_root",
        )
    resolved = (project_root / path).resolve(strict=False)
    try:
        resolved.relative_to(project_root)
    except ValueError as error:
        raise UniverseError(
            "PROJECT_REF_OUTSIDE_ROOT",
            f"{field} escapes project_root",
        ) from error
    return path.as_posix()


def _relative_ref(project_root: Path, value: Any, field: str) -> str:
    return _relative_project_path(project_root, value, f"refs.{field}")


def _project_file_ref(project_root: Path, value: Any, field: str) -> dict[str, str]:
    ref = _exact_object_fields(
        value,
        field=field,
        required=frozenset({"path", "sha256"}),
        optional=frozenset({"symbol", "kind"}),
    )
    relative_path = _relative_project_path(project_root, ref["path"], f"{field}.path")
    target = project_root / relative_path
    if not target.is_file() or target.is_symlink():
        raise UniverseError(
            "PROJECT_FILE_REF_UNAVAILABLE",
            f"{field}.path is not a regular project file: {relative_path}",
        )
    expected = _sha256(ref["sha256"], f"{field}.sha256")
    actual = hashlib.sha256(target.read_bytes()).hexdigest()
    if actual != expected:
        raise UniverseError(
            "PROJECT_FILE_REF_DIGEST_MISMATCH",
            f"{field}.sha256 does not match {relative_path}",
            HTTPStatus.CONFLICT,
        )
    normalized = {"path": relative_path, "sha256": expected}
    if "kind" in ref:
        normalized["kind"] = _identifier(ref["kind"], f"{field}.kind").upper()
    if "symbol" in ref:
        normalized["symbol"] = _required_text(ref["symbol"], f"{field}.symbol")
    return normalized


def _registration_network_role(metadata: Mapping[str, Any] | None) -> str | None:
    if not isinstance(metadata, Mapping):
        return None
    role = str(metadata.get("network_role") or "").strip().upper()
    if role in NETWORK_ANCHOR_ROLES:
        return role
    return None


def _resolve_registration_manifest_rel(
    project_root: Path,
    *,
    preferred: str,
    network_role: str | None,
) -> str:
    preferred_path = project_root / preferred
    if preferred_path.is_file():
        return preferred
    if network_role is None:
        raise UniverseError(
            "PROJECT_MANIFEST_UNAVAILABLE",
            f"manifest does not exist: {preferred}",
        )
    # Network anchors (Universe home / Career source) may use alternate
    # identity files when REPOSITORY_MANIFEST.md is not published yet.
    for candidate in (
        "REPOSITORY_MANIFEST.md",
        "VERSION_MANIFEST.md",
        "AGENTS.md",
        "README.md",
    ):
        if (project_root / candidate).is_file():
            return candidate
    raise UniverseError(
        "PROJECT_MANIFEST_UNAVAILABLE",
        "network anchor root has no identity manifest/README",
    )


def _node_tag_from_project_root(project_root: Path) -> str:
    """Return the default Node tag from the directory that owns `.ai`.

    Source-only Nodes can be registered before their local Workspace exists;
    their declared project root is still the future `.ai` parent and therefore
    yields the same tag after installation.
    """
    return project_root.resolve().name


def _read_node_manifest(node_root: Path) -> dict[str, Any] | None:
    try:
        manifest = json.loads((node_root / NODE_MANIFEST).read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return None
    return manifest if isinstance(manifest, dict) else None


def _node_candidate_from_manifest(
    node_root: Path,
    manifest: Mapping[str, Any],
    *,
    parent_project_id: str | None = None,
    logical_path: str | None = None,
) -> dict[str, Any] | None:
    if manifest.get("schema") != NODE_MANIFEST_SCHEMA:
        return None
    try:
        node_id = _project_id(manifest.get("node_id"))
        display_name = _required_text(manifest.get("display_name"), "display_name")
        node_kind = _required_text(manifest.get("kind"), "kind").upper()
        network_role = _required_text(
            manifest.get("network_role", "PRODUCT_NODE"), "network_role"
        ).upper()
        if node_kind not in NODE_KINDS or network_role not in NETWORK_ANCHOR_ROLES:
            return None
        legacy_raw = manifest.get("legacy_project_ids", [])
        if not isinstance(legacy_raw, list):
            return None
        legacy_project_ids = list(dict.fromkeys(_project_id(value) for value in legacy_raw))
    except UniverseError:
        return None
    metadata: dict[str, Any] = {
        "network_role": network_role,
        "node_kind": node_kind,
        "node_tag": _node_tag_from_project_root(node_root),
        "display_name": display_name,
        "label": _required_text(manifest.get("label", node_kind.title()), "label"),
        "legacy_project_ids": legacy_project_ids,
        "runtime_ownership": "OWNED",
    }
    if parent_project_id is not None:
        metadata["parent_project_id"] = parent_project_id
    if logical_path is not None:
        metadata["logical_path"] = logical_path
    return {
        "project_id": node_id,
        "project_root": node_root.resolve(),
        "metadata": metadata,
    }


def _discover_node_tree(node_root: Path) -> list[dict[str, Any]]:
    root_manifest = _read_node_manifest(node_root)
    if root_manifest is None:
        return []
    root_candidate = _node_candidate_from_manifest(
        node_root, root_manifest, logical_path="."
    )
    if root_candidate is None:
        return []
    candidates = [root_candidate]
    catalog_path = node_root / NODE_CATALOG_MANIFEST
    if not catalog_path.is_file():
        return candidates
    try:
        catalog = json.loads(catalog_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return candidates
    if not isinstance(catalog, dict) or catalog.get("schema") != NODE_CATALOG_SCHEMA:
        return candidates
    try:
        children_relative = Path(
            _required_text(catalog.get("children_root"), "children_root")
        )
        if children_relative.is_absolute() or ".." in children_relative.parts:
            return candidates
        children_root = (node_root / children_relative).resolve()
        if not children_root.is_relative_to(node_root) or not children_root.is_dir():
            return candidates
    except UniverseError:
        return candidates
    seen_ids = {root_candidate["project_id"]}
    for child_root in sorted(children_root.iterdir(), key=lambda entry: entry.name.casefold()):
        if not child_root.is_dir() or child_root.is_symlink():
            continue
        candidate = _node_candidate_from_manifest(
            child_root,
            _read_node_manifest(child_root) or {},
            parent_project_id=root_candidate["project_id"],
            logical_path=child_root.relative_to(node_root).as_posix(),
        )
        if candidate is None or candidate["project_id"] in seen_ids:
            continue
        seen_ids.add(candidate["project_id"])
        candidates.append(candidate)
    return candidates


def discover_network_anchor_candidates(
    *,
    universe_root: Path | None = None,
) -> list[dict[str, Any]]:
    """Discover manifest-defined Node trees from local Node root configuration."""
    home = (universe_root or Path(__file__).resolve().parents[1]).expanduser()
    home = home.resolve()
    roots = [home]
    configured_roots = os.environ.get(NODE_ROOTS_ENV, "")
    for raw_root in configured_roots.split(os.pathsep):
        if raw_root.strip():
            roots.append(Path(raw_root).expanduser().resolve())
    candidates: list[dict[str, Any]] = []
    seen_roots: set[Path] = set()
    seen_ids: set[str] = set()
    for node_root in roots:
        if node_root in seen_roots or not node_root.is_dir():
            continue
        seen_roots.add(node_root)
        for candidate in _discover_node_tree(node_root):
            if candidate["project_id"] in seen_ids:
                continue
            seen_ids.add(candidate["project_id"])
            candidates.append(candidate)
    return candidates


def ensure_network_anchor_projects(
    store: "UniverseStore",
    *,
    universe_root: Path | None = None,
) -> list[dict[str, Any]]:
    """Idempotently attach discovered network and product Nodes."""
    ensured: list[dict[str, Any]] = []
    for candidate in discover_network_anchor_candidates(universe_root=universe_root):
        root = Path(candidate["project_root"])
        if not root.is_dir():
            continue
        try:
            project, _created = store.register_project(
                {
                    "project_id": candidate["project_id"],
                    "project_root": str(root),
                    "metadata": dict(candidate.get("metadata") or {}),
                }
            )
            ensured.append(project)
        except UniverseError:
            # Skip unreadable / mismatched roots; do not block the service.
            continue
        for source_project_id in candidate.get("metadata", {}).get(
            "legacy_project_ids", []
        ):
            try:
                store.migrate_legacy_project_todos(
                    source_project_id=source_project_id,
                    target_project_id=candidate["project_id"],
                )
            except UniverseError as error:
                if error.code != "PROJECT_NOT_FOUND":
                    raise
    return ensured


def normalize_registration(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise UniverseError("REQUEST_INVALID", "registration body must be an object")
    project_id = _project_id(value.get("project_id"))
    project_root = _canonical_project_root(value.get("project_root"))

    metadata_value = value.get("metadata", {})
    if not isinstance(metadata_value, dict):
        raise UniverseError("PROJECT_METADATA_INVALID", "metadata must be an object")
    metadata = dict(metadata_value)
    node_tag = metadata.get("node_tag")
    if node_tag is None:
        metadata["node_tag"] = _node_tag_from_project_root(project_root)
    else:
        metadata["node_tag"] = _required_text(node_tag, "metadata.node_tag")
    network_role = _registration_network_role(metadata)
    legacy_install_mode = value.get("install_mode")
    if legacy_install_mode is None and "install_mode" in metadata:
        legacy_install_mode = metadata["install_mode"]
    attachment = normalize_project_attachment(
        value.get("attachment"),
        default_membership="LINKED",
        install_mode=legacy_install_mode,
    )

    refs_value = value.get("refs", DEFAULT_REFS)
    if not isinstance(refs_value, dict):
        raise UniverseError("PROJECT_REFS_INVALID", "refs must be an object")
    unknown_refs = set(refs_value) - ALLOWED_REF_KEYS
    if unknown_refs:
        raise UniverseError(
            "PROJECT_REFS_INVALID",
            f"unsupported refs: {', '.join(sorted(unknown_refs))}",
        )
    refs_merged = dict(DEFAULT_REFS)
    refs_merged.update(
        {key: refs_value[key] for key in refs_value if key in ALLOWED_REF_KEYS}
    )
    # Validate every caller-provided reference before inspecting the project.
    # Otherwise an escaped manifest can be reported as merely unavailable when
    # its root has no preferred manifest file.
    for key in refs_value:
        _relative_ref(project_root, refs_value[key], key)

    # Resolve manifest only after the supplied reference boundary is known to
    # be safe, so network anchors can still substitute an identity file.
    preferred_manifest = str(refs_merged["manifest"] or DEFAULT_REFS["manifest"])
    manifest_rel = _resolve_registration_manifest_rel(
        project_root,
        preferred=preferred_manifest,
        network_role=network_role,
    )
    refs_merged["manifest"] = manifest_rel
    refs = {
        key: _relative_ref(project_root, refs_merged.get(key, default), key)
        for key, default in DEFAULT_REFS.items()
    }
    # Re-bind manifest after relative normalization for substituted names.
    refs["manifest"] = _relative_ref(project_root, manifest_rel, "manifest")
    manifest_path = project_root / refs["manifest"]
    if not manifest_path.is_file():
        raise UniverseError(
            "PROJECT_MANIFEST_UNAVAILABLE",
            f"manifest does not exist: {refs['manifest']}",
        )

    mode_registry_path = project_root / refs["mode_registry"]
    if mode_registry_path.is_file():
        try:
            registry = json.loads(mode_registry_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as error:
            raise UniverseError("MODE_REGISTRY_INVALID", str(error)) from error
        owner = registry.get("owner") if isinstance(registry, dict) else None
        if isinstance(owner, str) and owner.casefold() != project_id.casefold():
            raise UniverseError(
                "PROJECT_IDENTITY_MISMATCH",
                "project_id does not match Mode Registry owner",
                HTTPStatus.CONFLICT,
            )
    elif network_role is None:
        # Ordinary projects keep existing strictness via manifest only;
        # missing registry is allowed today if file absent.
        pass

    return {
        "schema": PROJECT_SCHEMA,
        "project_id": project_id,
        "project_root": str(project_root),
        "refs": refs,
        "metadata": metadata,
        "attachment": attachment,
    }


def normalize_event(project_id: str, value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise UniverseError("REQUEST_INVALID", "event body must be an object")
    payload = value.get("payload", {})
    if not isinstance(payload, dict):
        raise UniverseError("EVENT_PAYLOAD_INVALID", "payload must be an object")
    event_id = value.get("event_id") or "event_" + uuid.uuid4().hex
    event_id = _required_text(event_id, "event_id")
    if len(event_id) > 160:
        raise UniverseError("EVENT_ID_INVALID", "event_id is too long")
    return {
        "schema": EVENT_SCHEMA,
        "event_id": event_id,
        "project_id": _project_id(project_id),
        "event_type": _event_type(value.get("event_type")),
        "payload": payload,
        "created_at": utc_now(),
    }


def normalize_todo(value: Any, *, updating: bool = False) -> dict[str, Any]:
    required = {
        "scope_kind",
        "title",
        "detail",
        "priority",
        "state",
        "source_kind",
        "sort_order",
    }
    if updating:
        required.add("revision")
    request = _exact_object_fields(
        value,
        field="todo",
        required=frozenset(required),
        optional=frozenset(
            {
                "todo_id", "project_id", "node_ref", "goal_id", "milestone_id",
                "universe_goal_id",
            }
        ),
    )
    scope_kind = _required_text(request["scope_kind"], "scope_kind").upper()
    if scope_kind not in TODO_SCOPE_KINDS:
        raise UniverseError(
            "TODO_SCOPE_INVALID",
            "scope_kind must be UNIVERSE, PROJECT, or NODE",
        )
    title = _required_text(request["title"], "title")
    if len(title) > 160:
        raise UniverseError("TODO_TITLE_INVALID", "title is too long")
    detail = request["detail"]
    if not isinstance(detail, str) or len(detail) > 4000:
        raise UniverseError(
            "TODO_DETAIL_INVALID",
            "detail must be a string no longer than 4000 characters",
        )
    priority = _required_text(request["priority"], "priority").upper()
    if priority != "AUTO" and priority not in TODO_PRIORITIES:
        raise UniverseError(
            "TODO_PRIORITY_INVALID",
            "priority must be AUTO, P0, P1, P2, or P3",
        )
    state = _required_text(request["state"], "state").upper()
    if state not in TODO_STATES:
        raise UniverseError(
            "TODO_STATE_INVALID",
            "state must be BACKLOG, READY, IN_PROGRESS, BLOCKED, or DONE",
        )
    source_kind = _required_text(request["source_kind"], "source_kind").upper()
    if source_kind not in TODO_SOURCE_KINDS:
        raise UniverseError(
            "TODO_SOURCE_INVALID",
            "source_kind must be USER, CONDUCTOR, or MASTER",
        )
    sort_order = request["sort_order"]
    if isinstance(sort_order, bool) or not isinstance(sort_order, int):
        raise UniverseError("TODO_SORT_ORDER_INVALID", "sort_order must be an integer")

    project_id = request.get("project_id")
    node_ref = request.get("node_ref")
    if scope_kind == "UNIVERSE":
        if project_id is not None or node_ref is not None:
            raise UniverseError(
                "TODO_SCOPE_COORDINATE_INVALID",
                "UNIVERSE Todo cannot bind a project or node",
            )
        normalized_project = None
        normalized_node = None
    elif scope_kind == "PROJECT":
        normalized_project = _project_id(project_id)
        if node_ref is not None:
            raise UniverseError(
                "TODO_SCOPE_COORDINATE_INVALID",
                "PROJECT Todo cannot bind a node",
            )
        normalized_node = None
    else:
        normalized_project = _project_id(project_id)
        normalized_node = _identifier(node_ref, "node_ref")

    normalized = {
        "scope_kind": scope_kind,
        "project_id": normalized_project,
        "node_ref": normalized_node,
        "title": title,
        "detail": detail,
        "priority": priority,
        "state": state,
        "source_kind": source_kind,
        "sort_order": sort_order,
        "goal_id": _optional_identifier(request.get("goal_id"), "goal_id"),
        "universe_goal_id": _optional_identifier(
            request.get("universe_goal_id"), "universe_goal_id"
        ),
        "milestone_id": _optional_identifier(
            request.get("milestone_id"), "milestone_id"
        ),
    }
    if "todo_id" in request:
        normalized["todo_id"] = _identifier(request["todo_id"], "todo_id")
    if updating:
        revision = request["revision"]
        if isinstance(revision, bool) or not isinstance(revision, int) or revision < 1:
            raise UniverseError(
                "TODO_REVISION_INVALID",
                "revision must be a positive integer",
            )
        normalized["revision"] = revision
    return normalized


def normalize_todo_mutation_request(value: Any) -> dict[str, Any]:
    request = _exact_object_fields(
        value,
        field="todo_mutation_request",
        required=frozenset(
            {
                "provider",
                "provider_session_ref",
                "session_id",
                "session_anchor_ref",
                "instruction_ref",
                "todo",
            }
        ),
        optional=frozenset({"schema", "ttl_seconds"}),
    )
    provider = _required_text(request["provider"], "provider").upper()
    if provider not in TODO_MUTATION_PROVIDERS:
        raise UniverseError(
            "TODO_MUTATION_PROVIDER_INVALID",
            "provider must be CODEX, CLAUDE, or GROK",
        )
    provider_session_ref = _required_text(
        request["provider_session_ref"], "provider_session_ref"
    )
    if len(provider_session_ref) > 1000:
        raise UniverseError(
            "TODO_MUTATION_PROVIDER_SESSION_REF_INVALID",
            "provider_session_ref is too long",
        )
    instruction_ref = _required_text(request["instruction_ref"], "instruction_ref")
    if len(instruction_ref) > 512:
        raise UniverseError(
            "TODO_MUTATION_INSTRUCTION_REF_INVALID",
            "instruction_ref is too long",
        )
    ttl_seconds = request.get("ttl_seconds", TODO_MUTATION_RECEIPT_TTL_SECONDS)
    if (
        isinstance(ttl_seconds, bool)
        or not isinstance(ttl_seconds, int)
        or ttl_seconds < 1
        or ttl_seconds > TODO_MUTATION_RECEIPT_MAX_TTL_SECONDS
    ):
        raise UniverseError(
            "TODO_MUTATION_TTL_INVALID",
            f"ttl_seconds must be between 1 and {TODO_MUTATION_RECEIPT_MAX_TTL_SECONDS}",
        )
    return {
        "provider": provider,
        "provider_session_ref": provider_session_ref,
        "session_id": _identifier(request["session_id"], "session_id"),
        "session_anchor_ref": _required_text(
            request["session_anchor_ref"], "session_anchor_ref"
        ),
        "instruction_ref": instruction_ref,
        "todo": request["todo"],
        "ttl_seconds": ttl_seconds,
    }


def normalize_todo_action_payload(todo_id: Any, value: Any) -> dict[str, Any]:
    normalized_todo_id = _identifier(todo_id, "todo_id")
    request = _exact_object_fields(
        value,
        field="todo action",
        required=frozenset({"action_id", "outcome", "source", "evidence_ref"}),
        optional=frozenset({"validation"}),
    )
    action_id = _required_text(request["action_id"], "action_id")
    if len(action_id) > 160:
        raise UniverseError("TODO_ACTION_ID_INVALID", "action_id is too long")
    outcome = _required_text(request["outcome"], "outcome").upper()
    desired_state = {
        "STARTED": "IN_PROGRESS",
        "COMPLETED": "DONE",
        "FAILED": "BLOCKED",
        "REOPENED": "READY",
    }.get(outcome)
    if desired_state is None:
        raise UniverseError(
            "TODO_ACTION_OUTCOME_INVALID",
            "outcome must be STARTED, COMPLETED, FAILED, or REOPENED",
        )
    source = _required_text(request["source"], "source").upper()
    if len(source) > 80:
        raise UniverseError("TODO_ACTION_SOURCE_INVALID", "source is too long")
    evidence_ref = _required_text(request["evidence_ref"], "evidence_ref")
    if len(evidence_ref) > 1000:
        raise UniverseError("TODO_ACTION_EVIDENCE_INVALID", "evidence_ref is too long")
    validation_value = request.get("validation")
    if validation_value is None:
        validation: dict[str, str] = {}
    else:
        if not isinstance(validation_value, Mapping) or set(validation_value) != {
            "status",
            "evidence_ref",
        }:
            raise UniverseError(
                "TODO_ACTION_VALIDATION_INVALID",
                "validation must contain only status and evidence_ref",
            )
        validation = {
            "status": _required_text(
                validation_value["status"], "validation.status"
            ).upper(),
            "evidence_ref": _required_text(
                validation_value["evidence_ref"], "validation.evidence_ref"
            ),
        }
    if outcome == "COMPLETED" and validation.get("status") != "PASSED":
        raise UniverseError(
            "TODO_COMPLETION_VALIDATION_REQUIRED",
            "COMPLETED requires validation.status PASSED and validation evidence",
            HTTPStatus.CONFLICT,
        )
    return {
        "todo_id": normalized_todo_id,
        "action_id": action_id,
        "outcome": outcome,
        "source": source,
        "evidence_ref": evidence_ref,
        "validation": validation,
        "state": desired_state,
    }


def normalize_todo_action_mutation_request(value: Any) -> dict[str, Any]:
    request = _exact_object_fields(
        value,
        field="todo_action_mutation_request",
        required=frozenset(
            {
                "provider",
                "provider_session_ref",
                "session_id",
                "session_anchor_ref",
                "instruction_ref",
                "todo_id",
                "action",
            }
        ),
        optional=frozenset({"schema", "ttl_seconds"}),
    )
    provider = _required_text(request["provider"], "provider").upper()
    if provider not in TODO_MUTATION_PROVIDERS:
        raise UniverseError(
            "TODO_MUTATION_PROVIDER_INVALID",
            "provider must be CODEX, CLAUDE, or GROK",
        )
    provider_session_ref = _required_text(
        request["provider_session_ref"], "provider_session_ref"
    )
    if len(provider_session_ref) > 1000:
        raise UniverseError(
            "TODO_MUTATION_PROVIDER_SESSION_REF_INVALID",
            "provider_session_ref is too long",
        )
    instruction_ref = _required_text(request["instruction_ref"], "instruction_ref")
    if len(instruction_ref) > 512:
        raise UniverseError(
            "TODO_MUTATION_INSTRUCTION_REF_INVALID",
            "instruction_ref is too long",
        )
    ttl_seconds = request.get("ttl_seconds", TODO_MUTATION_RECEIPT_TTL_SECONDS)
    if (
        isinstance(ttl_seconds, bool)
        or not isinstance(ttl_seconds, int)
        or ttl_seconds < 1
        or ttl_seconds > TODO_MUTATION_RECEIPT_MAX_TTL_SECONDS
    ):
        raise UniverseError(
            "TODO_MUTATION_TTL_INVALID",
            f"ttl_seconds must be between 1 and {TODO_MUTATION_RECEIPT_MAX_TTL_SECONDS}",
        )
    normalized_todo_id = _identifier(request["todo_id"], "todo_id")
    action = normalize_todo_action_payload(normalized_todo_id, request["action"])
    normalized_action = {
        key: action[key]
        for key in ("action_id", "outcome", "source", "evidence_ref")
    }
    # STARTED/FAILED/REOPENED actions do not require validation.  Keep the
    # canonical payload idempotent across the HTTP normalizer and the Store's
    # second defensive normalization instead of turning an absent value into
    # an invalid empty object.
    if action["validation"]:
        normalized_action["validation"] = action["validation"]
    return {
        "provider": provider,
        "provider_session_ref": provider_session_ref,
        "session_id": _identifier(request["session_id"], "session_id"),
        "session_anchor_ref": _required_text(
            request["session_anchor_ref"], "session_anchor_ref"
        ),
        "instruction_ref": instruction_ref,
        "todo_id": normalized_todo_id,
        "action": normalized_action,
        "ttl_seconds": ttl_seconds,
    }


def _optional_identifier(value: Any, field: str) -> str | None:
    if value is None or value == "":
        return None
    return _identifier(value, field)


def normalize_goal(project_id: str, value: Any, *, updating: bool = False) -> dict[str, Any]:
    required = {"title", "description", "owner", "state", "sort_order"}
    if updating:
        required.add("revision")
    request = _exact_object_fields(
        value,
        field="goal",
        required=frozenset(required),
        optional=frozenset({"goal_id", "universe_goal_id", "scope_kind", "node_ref"}),
    )
    title = _required_text(request["title"], "title")
    description = request["description"]
    if len(title) > 160 or not isinstance(description, str) or len(description) > 4000:
        raise UniverseError("GOAL_TEXT_INVALID", "goal title or description is too long")
    state = _required_text(request["state"], "state").upper()
    if state not in GOAL_STATES:
        raise UniverseError("GOAL_STATE_INVALID", "unsupported goal state")
    sort_order = request["sort_order"]
    if isinstance(sort_order, bool) or not isinstance(sort_order, int):
        raise UniverseError("GOAL_SORT_ORDER_INVALID", "sort_order must be an integer")
    scope_kind = _required_text(request.get("scope_kind", "PROJECT"), "scope_kind").upper()
    if scope_kind not in {"PROJECT", "NODE"}:
        raise UniverseError("GOAL_SCOPE_INVALID", "scope_kind must be PROJECT or NODE")
    node_ref = request.get("node_ref")
    if scope_kind == "PROJECT":
        if node_ref is not None:
            raise UniverseError("GOAL_SCOPE_COORDINATE_INVALID", "PROJECT Goal cannot bind a node")
        normalized_node = None
    else:
        normalized_node = _identifier(node_ref, "node_ref")
    normalized = {
        "project_id": _project_id(project_id),
        "scope_kind": scope_kind,
        "node_ref": normalized_node,
        "title": title,
        "description": description,
        "owner": _required_text(request["owner"], "owner"),
        "state": state,
        "sort_order": sort_order,
        "universe_goal_id": _optional_identifier(
            request.get("universe_goal_id"), "universe_goal_id"
        ),
    }
    if "goal_id" in request:
        normalized["goal_id"] = _identifier(request["goal_id"], "goal_id")
    if updating:
        revision = request["revision"]
        if isinstance(revision, bool) or not isinstance(revision, int) or revision < 1:
            raise UniverseError(
                "GOAL_REVISION_INVALID", "revision must be a positive integer"
            )
        normalized["revision"] = revision
    return normalized


