def infer_todo_priority(todo: Mapping[str, Any]) -> dict[str, Any]:
    """Return an explainable default; a user-selected P0..P3 always wins."""

    text = " ".join(
        str(todo.get(field) or "") for field in ("title", "detail")
    ).lower()
    score = 0
    reasons: list[str] = []
    if todo.get("scope_kind") == "UNIVERSE":
        score += 3
        reasons.append("universe-wide impact")
    elif todo.get("scope_kind") == "PROJECT":
        score += 2
        reasons.append("project-wide impact")
    elif todo.get("scope_kind") == "NODE":
        score += 1
        reasons.append("node-scoped work")
    if todo.get("state") in {"READY", "IN_PROGRESS", "BLOCKED"}:
        score += 1
        reasons.append("active delivery state")
    signals = {
        "failure": 3,
        "security": 3,
        "critical": 3,
        "release": 2,
        "runtime": 2,
        "migration": 2,
        "schema": 2,
        "anchor": 2,
        "foundation": 2,
        "global": 2,
        "collector": 1,
        "automation": 1,
        "documentation": -1,
        "desktop": -1,
    }
    for signal, weight in signals.items():
        if signal in text:
            score += weight
            reasons.append(f"signal: {signal}")
    if score >= 5:
        priority = "P0"
    elif score >= 3:
        priority = "P1"
    elif score >= 1:
        priority = "P2"
    else:
        priority = "P3"
    return {
        "priority": priority,
        "confidence": "HIGH" if abs(score) >= 5 else "MEDIUM" if abs(score) >= 3 else "LOW",
        "method": "STRUCTURED_SIGNAL_V1",
        "reasons": reasons or ["no material priority signal"],
    }


def normalize_milestone(goal_id: str, value: Any, *, updating: bool = False) -> dict[str, Any]:
    required = {"title", "description", "state", "sort_order"}
    if updating:
        required.add("revision")
    request = _exact_object_fields(
        value,
        field="milestone",
        required=frozenset(required),
        optional=frozenset({"milestone_id"}),
    )
    title = _required_text(request["title"], "title")
    description = request["description"]
    if len(title) > 160 or not isinstance(description, str) or len(description) > 4000:
        raise UniverseError(
            "MILESTONE_TEXT_INVALID", "milestone title or description is too long"
        )
    state = _required_text(request["state"], "state").upper()
    if state not in MILESTONE_STATES:
        raise UniverseError("MILESTONE_STATE_INVALID", "unsupported milestone state")
    sort_order = request["sort_order"]
    if isinstance(sort_order, bool) or not isinstance(sort_order, int):
        raise UniverseError(
            "MILESTONE_SORT_ORDER_INVALID", "sort_order must be an integer"
        )
    normalized = {
        "goal_id": _identifier(goal_id, "goal_id"),
        "title": title,
        "description": description,
        "state": state,
        "sort_order": sort_order,
    }
    if "milestone_id" in request:
        normalized["milestone_id"] = _identifier(
            request["milestone_id"], "milestone_id"
        )
    if updating:
        revision = request["revision"]
        if isinstance(revision, bool) or not isinstance(revision, int) or revision < 1:
            raise UniverseError(
                "MILESTONE_REVISION_INVALID", "revision must be a positive integer"
            )
        normalized["revision"] = revision
    return normalized


def normalize_goal_work_plan(value: Any) -> dict[str, Any]:
    plan = _exact_object_fields(
        value,
        field="goal_work_plan",
        required=frozenset({"title", "summary", "milestones"}),
        optional=frozenset({"schema"}),
    )
    if "schema" in plan and plan["schema"] != GOAL_WORK_PLAN_SCHEMA:
        raise UniverseError("GOAL_WORK_PLAN_SCHEMA_INVALID", "work plan schema is unsupported")
    title = _required_text(plan["title"], "goal_work_plan.title")
    summary = _required_text(plan["summary"], "goal_work_plan.summary")
    if len(title) > 160 or len(summary) > 1000:
        raise UniverseError("GOAL_WORK_PLAN_TEXT_INVALID", "work plan title or summary is too long")
    raw_milestones = plan["milestones"]
    if not isinstance(raw_milestones, list) or not 1 <= len(raw_milestones) <= 6:
        raise UniverseError("GOAL_WORK_PLAN_MILESTONES_INVALID", "work plan requires 1 to 6 milestones")
    milestones: list[dict[str, Any]] = []
    todo_count = 0
    for milestone_index, raw_milestone in enumerate(raw_milestones):
        milestone = _exact_object_fields(
            raw_milestone,
            field=f"goal_work_plan.milestones[{milestone_index}]",
            required=frozenset({"title", "description", "todos"}),
        )
        milestone_title = _required_text(milestone["title"], "milestone.title")
        milestone_description = _required_text(milestone["description"], "milestone.description")
        if len(milestone_title) > 160 or len(milestone_description) > 4000:
            raise UniverseError("GOAL_WORK_PLAN_MILESTONE_TEXT_INVALID", "work plan milestone text is too long")
        raw_todos = milestone["todos"]
        if not isinstance(raw_todos, list) or not 1 <= len(raw_todos) <= 8:
            raise UniverseError("GOAL_WORK_PLAN_TODOS_INVALID", "each work plan milestone requires 1 to 8 Todos")
        todos: list[dict[str, str]] = []
        for todo_index, raw_todo in enumerate(raw_todos):
            todo = _exact_object_fields(
                raw_todo,
                field=f"goal_work_plan.milestones[{milestone_index}].todos[{todo_index}]",
                required=frozenset({"title", "detail", "acceptance", "priority"}),
            )
            todo_title = _required_text(todo["title"], "todo.title")
            detail = _required_text(todo["detail"], "todo.detail")
            acceptance = _required_text(todo["acceptance"], "todo.acceptance")
            priority = _required_text(todo["priority"], "todo.priority").upper()
            if len(todo_title) > 160 or len(detail) > 3000 or len(acceptance) > 1000:
                raise UniverseError("GOAL_WORK_PLAN_TODO_TEXT_INVALID", "work plan Todo text is too long")
            if priority != "AUTO" and priority not in TODO_PRIORITIES:
                raise UniverseError("GOAL_WORK_PLAN_PRIORITY_INVALID", "work plan priority must be AUTO or P0 through P3")
            todos.append({"title": todo_title, "detail": detail, "acceptance": acceptance, "priority": priority})
            todo_count += 1
        milestones.append({"title": milestone_title, "description": milestone_description, "todos": todos})
    if todo_count > 24:
        raise UniverseError("GOAL_WORK_PLAN_TOO_LARGE", "work plan may contain at most 24 Todos")
    return {"schema": GOAL_WORK_PLAN_SCHEMA, "title": title, "summary": summary, "milestones": milestones}


def normalize_expected_path_route(value: Any) -> dict[str, Any]:
    route = _exact_object_fields(
        value,
        field="expected_path.route",
        required=frozenset(
            {
                "steps",
                "dependencies",
                "branches",
                "architecture_decisions",
                "implementation_phases",
                "risks",
                "acceptance_conditions",
                "estimates",
                "evidence_refs",
            }
        ),
        optional=frozenset({"schema"}),
    )
    if "schema" in route and route["schema"] != EXPECTED_PATH_ROUTE_SCHEMA:
        raise UniverseError("EXPECTED_PATH_ROUTE_SCHEMA_INVALID", "Expected Path route schema is unsupported")
    raw_steps = _array(route["steps"], "expected_path.route.steps")
    if not 1 <= len(raw_steps) <= 24:
        raise UniverseError("EXPECTED_PATH_ROUTE_STEPS_INVALID", "Expected Path route requires 1 to 24 steps")
    steps: list[dict[str, str]] = []
    step_ids: set[str] = set()
    for index, raw_step in enumerate(raw_steps):
        step = _exact_object_fields(
            raw_step,
            field=f"expected_path.route.steps[{index}]",
            required=frozenset({"step_id", "title", "summary"}),
            optional=frozenset({"phase"}),
        )
        step_id = _identifier(step["step_id"], "step_id")
        if step_id in step_ids:
            raise UniverseError("EXPECTED_PATH_ROUTE_STEP_DUPLICATE", "Expected Path step IDs must be unique")
        step_ids.add(step_id)
        title = _required_text(step["title"], "step.title")
        summary = _required_text(step["summary"], "step.summary")
        phase = str(step.get("phase") or "").strip()
        if len(title) > 160 or len(summary) > 1200 or len(phase) > 160:
            raise UniverseError("EXPECTED_PATH_ROUTE_STEP_TEXT_INVALID", "Expected Path step text is too long")
        material = {"step_id": step_id, "title": title, "summary": summary}
        if phase:
            material["phase"] = phase
        steps.append(material)

    dependencies: list[dict[str, str]] = []
    for index, raw_dependency in enumerate(_array(route["dependencies"], "expected_path.route.dependencies")):
        dependency = _exact_object_fields(
            raw_dependency,
            field=f"expected_path.route.dependencies[{index}]",
            required=frozenset({"from_step_id", "to_step_id", "kind"}),
        )
        source = _identifier(dependency["from_step_id"], "from_step_id")
        target = _identifier(dependency["to_step_id"], "to_step_id")
        kind = _identifier(dependency["kind"], "kind").upper()
        if source not in step_ids or target not in step_ids or source == target:
            raise UniverseError("EXPECTED_PATH_ROUTE_DEPENDENCY_INVALID", "dependencies must connect distinct route steps")
        if kind not in {"REQUIRES", "PRECEDES", "ENABLES"}:
            raise UniverseError("EXPECTED_PATH_ROUTE_DEPENDENCY_KIND_INVALID", "unsupported route dependency kind")
        dependencies.append({"from_step_id": source, "to_step_id": target, "kind": kind})
    if len(dependencies) > 64:
        raise UniverseError("EXPECTED_PATH_ROUTE_DEPENDENCIES_INVALID", "Expected Path route has too many dependencies")

    branches: list[dict[str, Any]] = []
    for index, raw_branch in enumerate(_array(route["branches"], "expected_path.route.branches")):
        branch = _exact_object_fields(
            raw_branch,
            field=f"expected_path.route.branches[{index}]",
            required=frozenset({"from_step_id", "condition", "to_step_ids"}),
        )
        source = _identifier(branch["from_step_id"], "from_step_id")
        targets = _string_array(branch["to_step_ids"], "to_step_ids")
        if source not in step_ids or not targets or any(target not in step_ids for target in targets):
            raise UniverseError("EXPECTED_PATH_ROUTE_BRANCH_INVALID", "branches must reference route steps")
        condition = _required_text(branch["condition"], "branch.condition")
        if len(condition) > 500:
            raise UniverseError("EXPECTED_PATH_ROUTE_BRANCH_INVALID", "branch condition is too long")
        branches.append({"from_step_id": source, "condition": condition, "to_step_ids": targets})
    if len(branches) > 24:
        raise UniverseError("EXPECTED_PATH_ROUTE_BRANCH_INVALID", "Expected Path route has too many branches")

    phases: list[dict[str, Any]] = []
    for index, raw_phase in enumerate(_array(route["implementation_phases"], "expected_path.route.implementation_phases")):
        phase = _exact_object_fields(
            raw_phase,
            field=f"expected_path.route.implementation_phases[{index}]",
            required=frozenset({"title", "step_ids"}),
        )
        title = _required_text(phase["title"], "phase.title")
        phase_steps = _string_array(phase["step_ids"], "phase.step_ids")
        if len(title) > 160 or not phase_steps or any(item not in step_ids for item in phase_steps):
            raise UniverseError("EXPECTED_PATH_ROUTE_PHASE_INVALID", "implementation phases must reference route steps")
        phases.append({"title": title, "step_ids": phase_steps})
    if not 1 <= len(phases) <= 12:
        raise UniverseError("EXPECTED_PATH_ROUTE_PHASE_INVALID", "Expected Path route requires 1 to 12 phases")

    risks: list[dict[str, str]] = []
    for index, raw_risk in enumerate(_array(route["risks"], "expected_path.route.risks")):
        risk = _exact_object_fields(
            raw_risk,
            field=f"expected_path.route.risks[{index}]",
            required=frozenset({"risk", "mitigation"}),
        )
        risk_text = _required_text(risk["risk"], "risk")
        mitigation = _required_text(risk["mitigation"], "mitigation")
        if len(risk_text) > 500 or len(mitigation) > 1000:
            raise UniverseError("EXPECTED_PATH_ROUTE_RISK_INVALID", "Expected Path risk text is too long")
        risks.append({"risk": risk_text, "mitigation": mitigation})
    if len(risks) > 16:
        raise UniverseError("EXPECTED_PATH_ROUTE_RISK_INVALID", "Expected Path route has too many risks")

    decisions = _string_array(route["architecture_decisions"], "architecture_decisions")
    acceptance = _string_array(route["acceptance_conditions"], "acceptance_conditions")
    evidence_refs = _string_array(route["evidence_refs"], "evidence_refs")
    if len(decisions) > 16 or len(acceptance) > 24 or len(evidence_refs) > 50:
        raise UniverseError("EXPECTED_PATH_ROUTE_LIST_INVALID", "Expected Path route list exceeds its limit")
    estimates = _exact_object_fields(
        route["estimates"],
        field="expected_path.route.estimates",
        required=frozenset({"effort", "cost", "quota"}),
    )
    normalized_estimates = {
        key: _required_text(estimates[key], f"estimates.{key}") for key in ("effort", "cost", "quota")
    }
    if any(len(item) > 500 for item in normalized_estimates.values()):
        raise UniverseError("EXPECTED_PATH_ROUTE_ESTIMATE_INVALID", "Expected Path estimate is too long")
    return {
        "schema": EXPECTED_PATH_ROUTE_SCHEMA,
        "steps": steps,
        "dependencies": dependencies,
        "branches": branches,
        "architecture_decisions": decisions,
        "implementation_phases": phases,
        "risks": risks,
        "acceptance_conditions": acceptance,
        "estimates": normalized_estimates,
        "evidence_refs": evidence_refs,
    }


def _array(value: Any, field: str) -> list[Any]:
    if not isinstance(value, list):
        raise UniverseError("REQUEST_INVALID", f"{field} must be an array")
    return list(value)


def _string_array(value: Any, field: str) -> list[str]:
    values = _array(value, field)
    normalized = [_required_text(item, f"{field}[]") for item in values]
    if len(set(normalized)) != len(normalized):
        raise UniverseError("REQUEST_INVALID", f"{field} must not contain duplicates")
    return normalized


def _observed_at(value: Any, field: str) -> str:
    text = _required_text(value, field)
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError as error:
        raise UniverseError(
            "OBSERVATION_TIME_INVALID",
            f"{field} must be an ISO-8601 timestamp",
        ) from error
    if parsed.tzinfo is None:
        raise UniverseError(
            "OBSERVATION_TIME_INVALID",
            f"{field} must include a timezone",
        )
    return (
        parsed.astimezone(timezone.utc)
        .isoformat(timespec="seconds")
        .replace("+00:00", "Z")
    )


def _lease_timestamp(value: Any, field: str) -> datetime:
    normalized = _observed_at(value, field)
    return datetime.fromisoformat(normalized.replace("Z", "+00:00"))


def _normalize_runtime_lease_request(value: Any) -> dict[str, Any]:
    request = _exact_object_fields(
        value,
        field="runtime_lease_activate",
        required=frozenset({"runtime_host_profile"}),
        optional=frozenset({"schema", "selected_release_id", "ttl_seconds"}),
    )
    schema = request.get("schema", RUNTIME_LEASE_SCHEMA)
    if schema != RUNTIME_LEASE_SCHEMA:
        raise UniverseError(
            "RUNTIME_LEASE_SCHEMA_INVALID",
            f"runtime lease schema must be {RUNTIME_LEASE_SCHEMA}",
        )
    runtime_host_profile = _required_text(
        request["runtime_host_profile"], "runtime_host_profile"
    ).upper()
    if not RUNTIME_HOST_PROFILE_PATTERN.fullmatch(runtime_host_profile):
        raise UniverseError(
            "RUNTIME_LEASE_HOST_PROFILE_INVALID",
            "runtime_host_profile must be an uppercase identifier",
        )
    selected_release_id = request.get("selected_release_id")
    if selected_release_id is not None:
        selected_release_id = _identifier(selected_release_id, "selected_release_id")
    ttl_seconds = request.get("ttl_seconds", RUNTIME_LEASE_DEFAULT_TTL_SECONDS)
    if (
        isinstance(ttl_seconds, bool)
        or not isinstance(ttl_seconds, int)
        or not 1 <= ttl_seconds <= RUNTIME_LEASE_MAX_TTL_SECONDS
    ):
        raise UniverseError(
            "RUNTIME_LEASE_TTL_INVALID",
            f"ttl_seconds must be an integer between 1 and {RUNTIME_LEASE_MAX_TTL_SECONDS}",
        )
    return {
        "schema": RUNTIME_LEASE_SCHEMA,
        "runtime_host_profile": runtime_host_profile,
        "selected_release_id": selected_release_id,
        "ttl_seconds": ttl_seconds,
    }


def _normalize_runtime_lease_control(
    value: Any,
    *,
    operation: str,
    optional: frozenset[str] = frozenset(),
) -> dict[str, Any]:
    request = _exact_object_fields(
        value,
        field=f"runtime_lease_{operation}",
        required=frozenset({"lease_id"}),
        optional=frozenset({"schema", *optional}),
    )
    schema = request.get("schema", RUNTIME_LEASE_SCHEMA)
    if schema != RUNTIME_LEASE_SCHEMA:
        raise UniverseError(
            "RUNTIME_LEASE_SCHEMA_INVALID",
            f"runtime lease schema must be {RUNTIME_LEASE_SCHEMA}",
        )
    request["lease_id"] = _required_text(request["lease_id"], "lease_id")
    return request


def _project_local_fallback(project: Mapping[str, Any]) -> dict[str, Any]:
    attachment = project["attachment"]
    origin = attachment["install_origin"]
    metadata = project.get("metadata")
    metadata = metadata if isinstance(metadata, Mapping) else {}
    declaration = metadata.get("local_fallback")
    declared = declaration is True or (
        isinstance(declaration, Mapping) and declaration.get("declared") is True
    )
    if origin == "PROJECT_STANDALONE":
        return {
            "status": "AVAILABLE",
            "runtime_host": "PROJECT_LOCAL",
            "declared": True,
            "reason": "PROJECT_STANDALONE_ORIGIN",
        }
    if origin == "UNIVERSE_CREATED" and declared:
        return {
            "status": "AVAILABLE",
            "runtime_host": "PROJECT_LOCAL",
            "declared": True,
            "reason": "DECLARED_LOCAL_FALLBACK",
        }
    return {
        "status": "UNAVAILABLE",
        "runtime_host": attachment["runtime_host"],
        "declared": False,
        "reason": "LOCAL_FALLBACK_NOT_DECLARED",
    }


def _skill_metrics(value: Any, field: str) -> dict[str, int | float]:
    metrics = _exact_object_fields(
        value,
        field=field,
        required=frozenset(),
        optional=SKILL_METRIC_KEYS,
    )
    normalized: dict[str, int | float] = {}
    for key, metric in metrics.items():
        if isinstance(metric, bool) or not isinstance(metric, (int, float)):
            raise UniverseError(
                "SKILL_METRICS_INVALID",
                f"{field}.{key} must be a non-negative number",
            )
        if not math.isfinite(metric) or metric < 0:
            raise UniverseError(
                "SKILL_METRICS_INVALID",
                f"{field}.{key} must be a non-negative number",
            )
        normalized[key] = metric
    return normalized


def normalize_skill_observation_candidate(
    project_id: str, value: Any
) -> dict[str, Any]:
    request = _exact_object_fields(
        value,
        field="skill_observation_request",
        required=frozenset({"candidate_id", "candidate"}),
    )
    candidate = _exact_object_fields(
        request["candidate"],
        field="skill_observation_candidate",
        required=frozenset(
            {
                "schema",
                "project_ref",
                "task_frame_ref",
                "source_ref",
                "observations",
                "observed_at",
                "target_ref",
                "redaction_state",
            }
        ),
    )
    normalized_project = _project_id(project_id)
    if candidate["schema"] != SKILL_OBSERVATION_CANDIDATE_SCHEMA:
        raise UniverseError(
            "SKILL_OBSERVATION_SCHEMA_INVALID",
            "candidate schema must be the ai-career redacted Skill observation schema",
        )
    if candidate["redaction_state"] != "REDACTED":
        raise UniverseError(
            "SKILL_OBSERVATION_REDACTION_REQUIRED",
            "Universe accepts only REDACTED Skill observation candidates",
        )
    expected_project_ref = f"project://{normalized_project}"
    if candidate["project_ref"] != expected_project_ref:
        raise UniverseError(
            "SKILL_OBSERVATION_PROJECT_MISMATCH",
            "candidate project_ref must match the attached project",
            HTTPStatus.CONFLICT,
        )
    observations = _array(candidate["observations"], "candidate.observations")
    if not observations or len(observations) > 256:
        raise UniverseError(
            "SKILL_OBSERVATION_COUNT_INVALID",
            "candidate.observations must contain 1..256 observations",
        )
    normalized_observations: list[dict[str, Any]] = []
    observation_digests: set[str] = set()
    for index, observation_value in enumerate(observations):
        field = f"candidate.observations[{index}]"
        observation = _exact_object_fields(
            observation_value,
            field=field,
            required=frozenset(
                {
                    "observation_digest",
                    "skill_binding_digest",
                    "skill",
                    "model_ref",
                    "outcome",
                    "validation_state",
                    "evidence_refs",
                    "metrics",
                }
            ),
            optional=frozenset({"execution_context"}),
        )
        skill = _exact_object_fields(
            observation["skill"],
            field=f"{field}.skill",
            required=frozenset(
                {"skill_id", "skill_version", "operation_class", "context_pack_digest"}
            ),
        )
        operation_class = _required_text(
            skill["operation_class"], f"{field}.skill.operation_class"
        ).upper()
        if operation_class not in SKILL_OPERATION_CLASSES:
            raise UniverseError(
                "SKILL_OPERATION_CLASS_INVALID",
                f"{field}.skill.operation_class is unsupported",
            )
        outcome = _required_text(observation["outcome"], f"{field}.outcome").upper()
        if outcome not in SKILL_OUTCOMES:
            raise UniverseError(
                "SKILL_OUTCOME_INVALID", f"{field}.outcome is unsupported"
            )
        validation_state = _required_text(
            observation["validation_state"], f"{field}.validation_state"
        ).upper()
        if validation_state not in SKILL_VALIDATION_STATES:
            raise UniverseError(
                "SKILL_VALIDATION_STATE_INVALID",
                f"{field}.validation_state is unsupported",
            )
        raw_execution_context = observation.get("execution_context")
        if raw_execution_context is None:
            execution_context = {
                "provider_ref": provider_ref_from_model_ref(
                    _required_text(observation["model_ref"], f"{field}.model_ref")
                ),
                "worker_role": "UNKNOWN",
                "task_kind": operation_class,
                "node_ref": "UNKNOWN",
                "failure_kind": "NONE" if outcome == "SUCCEEDED" else "UNKNOWN",
                "quota_state": "UNKNOWN",
            }
        else:
            context = _exact_object_fields(
                raw_execution_context,
                field=f"{field}.execution_context",
                required=frozenset(
                    {
                        "provider_ref",
                        "worker_role",
                        "task_kind",
                        "node_ref",
                        "failure_kind",
                        "quota_state",
                    }
                ),
            )
            failure_kind = _required_text(
                context["failure_kind"], f"{field}.execution_context.failure_kind"
            ).upper()
            quota_state = _required_text(
                context["quota_state"], f"{field}.execution_context.quota_state"
            ).upper()
            if failure_kind not in SKILL_FAILURE_KINDS:
                raise UniverseError(
                    "SKILL_FAILURE_KIND_INVALID",
                    f"{field}.execution_context.failure_kind is unsupported",
                )
            if quota_state not in SKILL_QUOTA_STATES:
                raise UniverseError(
                    "SKILL_QUOTA_STATE_INVALID",
                    f"{field}.execution_context.quota_state is unsupported",
                )
            execution_context = {
                "provider_ref": _required_text(
                    context["provider_ref"],
                    f"{field}.execution_context.provider_ref",
                ),
                "worker_role": _required_text(
                    context["worker_role"],
                    f"{field}.execution_context.worker_role",
                ).upper(),
                "task_kind": _required_text(
                    context["task_kind"], f"{field}.execution_context.task_kind"
                ).upper(),
                "node_ref": _required_text(
                    context["node_ref"], f"{field}.execution_context.node_ref"
                ),
                "failure_kind": failure_kind,
                "quota_state": quota_state,
            }
        observation_digest = _sha256(
            observation["observation_digest"], f"{field}.observation_digest"
        )
        if observation_digest in observation_digests:
            raise UniverseError(
                "SKILL_OBSERVATION_DUPLICATE",
                "candidate.observations must not repeat observation_digest",
            )
        observation_digests.add(observation_digest)
        normalized_observations.append(
            {
                "observation_digest": observation_digest,
                "skill_binding_digest": _sha256(
                    observation["skill_binding_digest"], f"{field}.skill_binding_digest"
                ),
                "skill": {
                    "skill_id": _identifier(
                        skill["skill_id"], f"{field}.skill.skill_id"
                    ),
                    "skill_version": _required_text(
                        skill["skill_version"], f"{field}.skill.skill_version"
                    ),
                    "operation_class": operation_class,
                    "context_pack_digest": _sha256(
                        skill["context_pack_digest"],
                        f"{field}.skill.context_pack_digest",
                    ),
                },
                "model_ref": _required_text(
                    observation["model_ref"], f"{field}.model_ref"
                ),
                "outcome": outcome,
                "validation_state": validation_state,
                "evidence_refs": _string_array(
                    observation["evidence_refs"], f"{field}.evidence_refs"
                ),
                "metrics": _skill_metrics(observation["metrics"], f"{field}.metrics"),
                "execution_context": execution_context,
            }
        )
    normalized_candidate = {
        "schema": SKILL_OBSERVATION_CANDIDATE_SCHEMA,
        "project_ref": expected_project_ref,
        "task_frame_ref": _required_text(
            candidate["task_frame_ref"], "candidate.task_frame_ref"
        ),
        "source_ref": _required_text(candidate["source_ref"], "candidate.source_ref"),
        "observations": normalized_observations,
        "observed_at": _observed_at(candidate["observed_at"], "candidate.observed_at"),
        "target_ref": _required_text(candidate["target_ref"], "candidate.target_ref"),
        "redaction_state": "REDACTED",
    }
    return {
        "candidate_id": _identifier(request["candidate_id"], "candidate_id"),
        "candidate": normalized_candidate,
        "candidate_digest": _json_sha256(normalized_candidate),
    }


def normalize_skill_observation_publication(
    project_id: str, value: Any
) -> dict[str, Any]:
    request = _exact_object_fields(
        value,
        field="skill_observation_publication",
        required=frozenset({"candidate_id", "candidate", "publication_approval"}),
    )
    normalized = normalize_skill_observation_candidate(
        project_id,
        {
            "candidate_id": request["candidate_id"],
            "candidate": request["candidate"],
        },
    )
    approval = _exact_object_fields(
        request["publication_approval"],
        field="publication_approval",
        required=frozenset(
            {
                "schema",
                "status",
                "operation_class",
                "project_ref",
                "candidate_id",
                "candidate_digest",
                "selection_ref",
                "approver",
                "evidence_ref",
            }
        ),
    )
    expected_project_ref = f"project://{_project_id(project_id)}"
    expected = {
        "schema": SKILL_OBSERVATION_PUBLICATION_APPROVAL_SCHEMA,
        "status": "APPROVED",
        "operation_class": "UNIVERSE_OBSERVATION_QUEUE",
        "project_ref": expected_project_ref,
        "candidate_id": normalized["candidate_id"],
        "candidate_digest": normalized["candidate_digest"],
        "approver": "PROJECT_MASTER",
    }
    mismatch = next(
        (
            field
            for field, expected_value in expected.items()
            if approval.get(field) != expected_value
        ),
        None,
    )
    if mismatch is not None:
        raise UniverseError(
            "SKILL_OBSERVATION_PUBLICATION_APPROVAL_MISMATCH",
            f"publication_approval.{mismatch} does not match the prepared candidate",
            HTTPStatus.CONFLICT,
        )
    normalized_approval = {
        **expected,
        "selection_ref": _required_text(
            approval["selection_ref"], "publication_approval.selection_ref"
        ),
        "evidence_ref": _required_text(
            approval["evidence_ref"], "publication_approval.evidence_ref"
        ),
    }
    return {
        **normalized,
        "publication_approval": normalized_approval,
        "publication_approval_digest": _json_sha256(normalized_approval),
    }


def normalize_fresh_project_intent(value: Any) -> dict[str, Any]:
    request = _exact_object_fields(
        value,
        field="fresh_project_intent",
        required=frozenset({"project", "kind", "technologies", "goal"}),
        optional=frozenset({"limit"}),
    )
    technologies = _string_array(request["technologies"], "technologies")
    if len(technologies) > 64:
        raise UniverseError(
            "FRESH_PROJECT_TECHNOLOGIES_INVALID",
            "technologies must contain at most 64 entries",
        )
    limit = request.get("limit", 3)
    if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 10:
        raise UniverseError(
            "FRESH_PROJECT_LIMIT_INVALID",
            "limit must be an integer from 1 through 10",
        )
    return {
        "project": _required_text(request["project"], "project"),
        "kind": _required_text(request["kind"], "kind"),
        "technologies": technologies,
        "goal": _required_text(request["goal"], "goal"),
        "limit": limit,
    }


def normalize_fresh_project_composition_request(value: Any) -> dict[str, Any]:
    request = _exact_object_fields(
        value,
        field="fresh_project_composition_request",
        required=frozenset({"intent", "route_id"}),
    )
    intent = _exact_object_fields(
        request["intent"],
        field="fresh_project_composition_request.intent",
        required=frozenset({"project", "kind", "technologies", "goal"}),
        optional=frozenset({"constraints", "project_root", "target_users"}),
    )
    normalized_intent = normalize_fresh_project_intent(
        {
            "project": intent["project"],
            "kind": intent["kind"],
            "technologies": intent["technologies"],
            "goal": intent["goal"],
        }
    )
    constraints = _string_array(intent.get("constraints", []), "intent.constraints")
    if len(constraints) > 32:
        raise UniverseError(
            "FRESH_PROJECT_CONSTRAINTS_INVALID",
            "intent.constraints must contain at most 32 entries",
        )
    normalized_intent["constraints"] = constraints
    if "project_root" in intent:
        normalized_intent["project_root"] = str(
            _canonical_project_root(intent["project_root"])
        )
    if "target_users" in intent:
        normalized_intent["target_users"] = _required_text(
            intent["target_users"], "intent.target_users"
        )
    return {
        "intent": normalized_intent,
        "route_id": _identifier(request["route_id"], "route_id"),
    }


