    @staticmethod
    def _goal_automation_scheduler_mutation_receipt_row(
        row: sqlite3.Row,
    ) -> dict[str, Any]:
        return {
            "schema": "universe.goal-automation-scheduler-mutation-receipt.v1",
            "receipt_id": row["receipt_id"],
            "session_id": row["session_id"],
            "session_anchor_ref": row["session_anchor_ref"],
            "provider": row["provider"],
            "provider_session_ref_hash": row["provider_session_ref_hash"],
            "instruction_ref": row["instruction_ref"],
            "goal_id": row["goal_id"],
            "payload_sha256": row["payload_sha256"],
            "status": row["status"],
            "prepared_at": row["prepared_at"],
            "expires_at": row["expires_at"],
            "consumed_at": row["consumed_at"],
        }

    @staticmethod
    def _bound_goal_automation_scheduler_mutation(
        request: Mapping[str, Any],
    ) -> tuple[dict[str, Any], str, str]:
        scheduler = normalize_goal_automation_scheduler_request(
            request["scheduler"]
        )
        payload_sha256 = _json_sha256(
            {"goal_id": request["goal_id"], "scheduler": scheduler}
        )
        provider_ref_hash = hashlib.sha256(
            str(request["provider_session_ref"]).encode("utf-8")
        ).hexdigest()
        return scheduler, payload_sha256, provider_ref_hash

    def prepare_goal_automation_scheduler_mutation_receipt(
        self, request: Mapping[str, Any]
    ) -> tuple[dict[str, Any], bool]:
        scheduler, payload_sha256, provider_ref_hash = (
            self._bound_goal_automation_scheduler_mutation(request)
        )
        now_datetime = datetime.now(timezone.utc).replace(microsecond=0)
        now = now_datetime.isoformat().replace("+00:00", "Z")
        expires_at = (
            now_datetime + timedelta(seconds=int(request["ttl_seconds"]))
        ).isoformat().replace("+00:00", "Z")
        receipt_id = "goal_scheduler_receipt_" + _json_sha256(
            {
                "session_id": request["session_id"],
                "instruction_ref": request["instruction_ref"],
            }
        )[:24]
        with self._connection() as connection:
            connection.execute("BEGIN IMMEDIATE")
            existing = connection.execute(
                """
                SELECT * FROM goal_automation_scheduler_mutation_receipt
                WHERE session_id = ? AND instruction_ref = ?
                """,
                (request["session_id"], request["instruction_ref"]),
            ).fetchone()
            if existing is not None:
                expected = (
                    request["session_anchor_ref"],
                    request["provider"],
                    provider_ref_hash,
                    request["goal_id"],
                    payload_sha256,
                )
                actual = (
                    existing["session_anchor_ref"],
                    existing["provider"],
                    existing["provider_session_ref_hash"],
                    existing["goal_id"],
                    existing["payload_sha256"],
                )
                if actual != expected:
                    raise UniverseError(
                        "GOAL_AUTOMATION_SCHEDULER_MUTATION_RECEIPT_CONFLICT",
                        "instruction_ref is already bound to different scheduler material",
                        HTTPStatus.CONFLICT,
                    )
                if existing["status"] == "PREPARED" and datetime.fromisoformat(
                    str(existing["expires_at"]).replace("Z", "+00:00")
                ) <= now_datetime:
                    connection.execute(
                        """
                        UPDATE goal_automation_scheduler_mutation_receipt
                        SET prepared_at = ?, expires_at = ? WHERE receipt_id = ?
                        """,
                        (now, expires_at, existing["receipt_id"]),
                    )
                    existing = connection.execute(
                        """
                        SELECT * FROM goal_automation_scheduler_mutation_receipt
                        WHERE receipt_id = ?
                        """,
                        (existing["receipt_id"],),
                    ).fetchone()
                return (
                    self._goal_automation_scheduler_mutation_receipt_row(existing),
                    False,
                )
            goal = connection.execute(
                "SELECT revision FROM project_goal WHERE goal_id = ?",
                (request["goal_id"],),
            ).fetchone()
            if goal is None:
                raise UniverseError(
                    "GOAL_NOT_FOUND", "Goal does not exist", HTTPStatus.NOT_FOUND
                )
            if int(goal["revision"]) != scheduler["expected_goal_revision"]:
                raise UniverseError(
                    "GOAL_REVISION_CONFLICT",
                    "Goal revision changed before scheduler receipt preparation",
                    HTTPStatus.CONFLICT,
                )
            connection.execute(
                """
                INSERT INTO goal_automation_scheduler_mutation_receipt(
                    receipt_id, session_id, session_anchor_ref, provider,
                    provider_session_ref_hash, instruction_ref, goal_id,
                    payload_sha256, status, prepared_at, expires_at, consumed_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'PREPARED', ?, ?, NULL)
                """,
                (
                    receipt_id,
                    request["session_id"],
                    request["session_anchor_ref"],
                    request["provider"],
                    provider_ref_hash,
                    request["instruction_ref"],
                    request["goal_id"],
                    payload_sha256,
                    now,
                    expires_at,
                ),
            )
            row = connection.execute(
                """
                SELECT * FROM goal_automation_scheduler_mutation_receipt
                WHERE receipt_id = ?
                """,
                (receipt_id,),
            ).fetchone()
        assert row is not None
        return self._goal_automation_scheduler_mutation_receipt_row(row), True

    def consume_goal_automation_scheduler_mutation_receipt(
        self, receipt_id: str, request: Mapping[str, Any]
    ) -> tuple[dict[str, Any], dict[str, Any], bool]:
        normalized_receipt_id = _identifier(receipt_id, "receipt_id")
        scheduler_request, payload_sha256, provider_ref_hash = (
            self._bound_goal_automation_scheduler_mutation(request)
        )
        now_datetime = datetime.now(timezone.utc).replace(microsecond=0)
        now = now_datetime.isoformat().replace("+00:00", "Z")
        with self._connection() as connection:
            connection.execute("BEGIN IMMEDIATE")
            receipt = connection.execute(
                """
                SELECT * FROM goal_automation_scheduler_mutation_receipt
                WHERE receipt_id = ?
                """,
                (normalized_receipt_id,),
            ).fetchone()
            if receipt is None:
                raise UniverseError(
                    "GOAL_AUTOMATION_SCHEDULER_MUTATION_RECEIPT_NOT_FOUND",
                    "Scheduler mutation receipt does not exist",
                    HTTPStatus.NOT_FOUND,
                )
            expected = (
                request["session_id"],
                request["session_anchor_ref"],
                request["provider"],
                provider_ref_hash,
                request["instruction_ref"],
                request["goal_id"],
                payload_sha256,
            )
            actual = (
                receipt["session_id"],
                receipt["session_anchor_ref"],
                receipt["provider"],
                receipt["provider_session_ref_hash"],
                receipt["instruction_ref"],
                receipt["goal_id"],
                receipt["payload_sha256"],
            )
            if actual != expected:
                raise UniverseError(
                    "GOAL_AUTOMATION_SCHEDULER_MUTATION_RECEIPT_REPLAY_CONFLICT",
                    "receipt is not bound to this session, Anchor, instruction, Goal, and scheduler payload",
                    HTTPStatus.CONFLICT,
                )
            if receipt["status"] == "CONSUMED":
                row = connection.execute(
                    "SELECT * FROM goal_automation_scheduler WHERE goal_id = ?",
                    (request["goal_id"],),
                ).fetchone()
                if row is None:
                    raise UniverseError(
                        "GOAL_AUTOMATION_SCHEDULER_MUTATION_RECEIPT_CORRUPT",
                        "consumed receipt has no scheduler state",
                        HTTPStatus.CONFLICT,
                    )
                return (
                    self._goal_automation_scheduler_mutation_receipt_row(receipt),
                    self._goal_automation_scheduler_row(row),
                    True,
                )
            if datetime.fromisoformat(
                str(receipt["expires_at"]).replace("Z", "+00:00")
            ) <= now_datetime:
                raise UniverseError(
                    "GOAL_AUTOMATION_SCHEDULER_MUTATION_RECEIPT_EXPIRED",
                    "Scheduler mutation receipt expired before consumption",
                    HTTPStatus.CONFLICT,
                )
            scheduler, _created = (
                self._configure_goal_automation_scheduler_in_connection(
                    connection,
                    request["goal_id"],
                    action=scheduler_request["action"],
                    expected_goal_revision=scheduler_request[
                        "expected_goal_revision"
                    ],
                    interval_seconds=scheduler_request["interval_seconds"],
                )
            )
            updated = connection.execute(
                """
                UPDATE goal_automation_scheduler_mutation_receipt
                SET status = 'CONSUMED', consumed_at = ?
                WHERE receipt_id = ? AND status = 'PREPARED'
                """,
                (now, normalized_receipt_id),
            )
            if updated.rowcount != 1:
                raise UniverseError(
                    "GOAL_AUTOMATION_SCHEDULER_MUTATION_RECEIPT_REPLAY_CONFLICT",
                    "Scheduler mutation receipt changed during consumption",
                    HTTPStatus.CONFLICT,
                )
            receipt = connection.execute(
                """
                SELECT * FROM goal_automation_scheduler_mutation_receipt
                WHERE receipt_id = ?
                """,
                (normalized_receipt_id,),
            ).fetchone()
        assert receipt is not None
        return (
            self._goal_automation_scheduler_mutation_receipt_row(receipt),
            scheduler,
            False,
        )

    @staticmethod
    def _goal_automation_scheduler_row(row: sqlite3.Row) -> dict[str, Any]:
        return {
            "schema": GOAL_AUTOMATION_SCHEDULER_SCHEMA,
            "goal_id": str(row["goal_id"]),
            "expected_goal_revision": int(row["expected_goal_revision"]),
            "enabled": bool(row["enabled"]),
            "status": str(row["status"]),
            "interval_seconds": int(row["interval_seconds"]),
            "next_tick_at": row["next_tick_at"],
            "lease_owner": row["lease_owner"],
            "lease_expires_at": row["lease_expires_at"],
            "last_tick_at": row["last_tick_at"],
            "last_stop_reason": row["last_stop_reason"],
            "last_error_code": row["last_error_code"],
            "last_error_detail": row["last_error_detail"],
            "last_surface": json.loads(str(row["last_surface_json"] or "{}")),
            "tick_count": int(row["tick_count"]),
            "revision": int(row["revision"]),
            "created_at": str(row["created_at"]),
            "updated_at": str(row["updated_at"]),
        }

    def get_goal_automation_scheduler(
        self, goal_id: str
    ) -> dict[str, Any] | None:
        normalized_goal = _identifier(goal_id, "goal_id")
        with self._connection() as connection:
            row = connection.execute(
                "SELECT * FROM goal_automation_scheduler WHERE goal_id = ?",
                (normalized_goal,),
            ).fetchone()
        return None if row is None else self._goal_automation_scheduler_row(row)

    def configure_goal_automation_scheduler(
        self,
        goal_id: str,
        *,
        action: str,
        expected_goal_revision: int,
        interval_seconds: int,
    ) -> tuple[dict[str, Any], bool]:
        normalized_goal = _identifier(goal_id, "goal_id")
        with self._connection() as connection:
            connection.execute("BEGIN IMMEDIATE")
            return self._configure_goal_automation_scheduler_in_connection(
                connection,
                normalized_goal,
                action=action,
                expected_goal_revision=expected_goal_revision,
                interval_seconds=interval_seconds,
            )

    def _configure_goal_automation_scheduler_in_connection(
        self,
        connection: sqlite3.Connection,
        goal_id: str,
        *,
        action: str,
        expected_goal_revision: int,
        interval_seconds: int,
    ) -> tuple[dict[str, Any], bool]:
        goal = connection.execute(
            "SELECT revision FROM project_goal WHERE goal_id = ?", (goal_id,)
        ).fetchone()
        if goal is None:
            raise UniverseError(
                "GOAL_NOT_FOUND", "Goal does not exist", HTTPStatus.NOT_FOUND
            )
        if int(goal["revision"]) != expected_goal_revision:
            raise UniverseError(
                "GOAL_REVISION_CONFLICT",
                "Goal revision changed before scheduler configuration",
                HTTPStatus.CONFLICT,
            )
        now = utc_now()
        existing = connection.execute(
            "SELECT * FROM goal_automation_scheduler WHERE goal_id = ?",
            (goal_id,),
        ).fetchone()
        if existing is None:
            connection.execute(
                """
                INSERT INTO goal_automation_scheduler(
                    goal_id, expected_goal_revision, enabled, status,
                    interval_seconds, next_tick_at, lease_owner,
                    lease_expires_at, last_tick_at, last_stop_reason,
                    last_error_code, last_error_detail, last_surface_json,
                    tick_count, revision, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, NULL, NULL, NULL, ?, NULL, NULL,
                          '{}', 0, 1, ?, ?)
                """,
                (
                    goal_id,
                    expected_goal_revision,
                    1 if action == "START" else 0,
                    "READY" if action == "START" else "PAUSED",
                    interval_seconds,
                    now if action == "START" else None,
                    None if action == "START" else "USER_PAUSED",
                    now,
                    now,
                ),
            )
            created = True
        else:
            connection.execute(
                """
                UPDATE goal_automation_scheduler
                SET expected_goal_revision = ?, enabled = ?, status = ?,
                    interval_seconds = ?, next_tick_at = ?, lease_owner = NULL,
                    lease_expires_at = NULL, last_stop_reason = ?,
                    last_error_code = NULL, last_error_detail = NULL,
                    revision = revision + 1, updated_at = ?
                WHERE goal_id = ?
                """,
                (
                    expected_goal_revision,
                    1 if action == "START" else 0,
                    "READY" if action == "START" else "PAUSED",
                    interval_seconds,
                    now if action == "START" else None,
                    None if action == "START" else "USER_PAUSED",
                    now,
                    goal_id,
                ),
            )
            created = False
        row = connection.execute(
            "SELECT * FROM goal_automation_scheduler WHERE goal_id = ?",
            (goal_id,),
        ).fetchone()
        assert row is not None
        return self._goal_automation_scheduler_row(row), created

    def claim_due_goal_automation_scheduler(
        self, lease_owner: str, *, lease_seconds: int = 15
    ) -> dict[str, Any] | None:
        owner = _required_text(lease_owner, "lease_owner")
        now_datetime = datetime.now(timezone.utc).replace(microsecond=0)
        now = now_datetime.isoformat().replace("+00:00", "Z")
        expires_at = (
            now_datetime + timedelta(seconds=max(1, min(int(lease_seconds), 300)))
        ).isoformat().replace("+00:00", "Z")
        with self._connection() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute(
                """
                SELECT * FROM goal_automation_scheduler
                WHERE enabled = 1 AND status IN ('READY', 'RUNNING')
                  AND next_tick_at IS NOT NULL AND next_tick_at <= ?
                  AND (lease_expires_at IS NULL OR lease_expires_at <= ?)
                ORDER BY next_tick_at, goal_id
                LIMIT 1
                """,
                (now, now),
            ).fetchone()
            if row is None:
                return None
            updated = connection.execute(
                """
                UPDATE goal_automation_scheduler
                SET status = 'RUNNING', lease_owner = ?, lease_expires_at = ?,
                    revision = revision + 1, updated_at = ?
                WHERE goal_id = ? AND revision = ?
                """,
                (owner, expires_at, now, row["goal_id"], row["revision"]),
            )
            if updated.rowcount != 1:
                return None
            claimed = connection.execute(
                "SELECT * FROM goal_automation_scheduler WHERE goal_id = ?",
                (row["goal_id"],),
            ).fetchone()
        assert claimed is not None
        return self._goal_automation_scheduler_row(claimed)

    def finish_goal_automation_scheduler_tick(
        self,
        goal_id: str,
        *,
        lease_owner: str,
        status: str,
        stop_reason: str,
        surface: Mapping[str, Any] | None,
        error_code: str | None = None,
        error_detail: str | None = None,
    ) -> dict[str, Any]:
        normalized_goal = _identifier(goal_id, "goal_id")
        owner = _required_text(lease_owner, "lease_owner")
        normalized_status = _required_text(status, "status").upper()
        if normalized_status not in {"WAITING", "BLOCKED", "COMPLETED"}:
            raise UniverseError(
                "GOAL_AUTOMATION_SCHEDULER_STATUS_INVALID",
                "scheduler tick status must be WAITING, BLOCKED, or COMPLETED",
            )
        now = utc_now()
        with self._connection() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute(
                "SELECT * FROM goal_automation_scheduler WHERE goal_id = ?",
                (normalized_goal,),
            ).fetchone()
            if row is None:
                raise UniverseError(
                    "GOAL_AUTOMATION_SCHEDULER_NOT_FOUND",
                    "Goal automation scheduler does not exist",
                    HTTPStatus.NOT_FOUND,
                )
            if row["lease_owner"] != owner or row["status"] != "RUNNING":
                raise UniverseError(
                    "GOAL_AUTOMATION_SCHEDULER_LEASE_MISMATCH",
                    "scheduler tick no longer owns the durable lease",
                    HTTPStatus.CONFLICT,
                )
            connection.execute(
                """
                UPDATE goal_automation_scheduler
                SET enabled = 0, status = ?, next_tick_at = NULL,
                    lease_owner = NULL, lease_expires_at = NULL,
                    last_tick_at = ?, last_stop_reason = ?,
                    last_error_code = ?, last_error_detail = ?,
                    last_surface_json = ?, tick_count = tick_count + 1,
                    revision = revision + 1, updated_at = ?
                WHERE goal_id = ?
                """,
                (
                    normalized_status,
                    now,
                    _required_text(stop_reason, "stop_reason"),
                    error_code,
                    error_detail,
                    _canonical_json(dict(surface or {})),
                    now,
                    normalized_goal,
                ),
            )
            finished = connection.execute(
                "SELECT * FROM goal_automation_scheduler WHERE goal_id = ?",
                (normalized_goal,),
            ).fetchone()
        assert finished is not None
        return self._goal_automation_scheduler_row(finished)

    @staticmethod
    def _master_handoff_task_frame_binding_row(row: sqlite3.Row) -> dict[str, Any]:
        return {
            "schema": PROJECT_MASTER_HANDOFF_TASK_FRAME_BINDING_SCHEMA,
            "project_id": str(row["project_id"]),
            "handoff_id": str(row["handoff_id"]),
            "instruction_ref": str(row["instruction_ref"]),
            "proposal_id": str(row["proposal_id"]),
            "proposal_digest": str(row["proposal_digest"]),
            "task_frame_id": str(row["task_frame_id"]),
            "binding_digest": str(row["binding_digest"]),
            "bound_at": str(row["bound_at"]),
        }

    def list_master_handoffs(
        self, project_id: str, *, limit: int = 100
    ) -> list[dict[str, Any]]:
        project = self.get_project(project_id)
        with self._connection() as connection:
            rows = connection.execute(
                """
                SELECT handoff_json, delivery_state, room_message_id, created_at, delivered_at
                FROM project_master_handoff
                WHERE project_id = ?
                ORDER BY created_at DESC, handoff_id DESC
                LIMIT ?
                """,
                (project["project_id"], max(1, min(int(limit), 500))),
            ).fetchall()
        return [self._master_handoff_row(row) for row in rows]

    def get_skill_plan_master_application(
        self,
        project_id: str,
        handoff_id: str,
    ) -> dict[str, Any] | None:
        project = self.get_project(project_id)
        normalized_handoff_id = _identifier(handoff_id, "handoff_id")
        with self._connection() as connection:
            row = connection.execute(
                """
                SELECT application_json, applied_at
                FROM project_skill_plan_master_application
                WHERE project_id = ? AND handoff_id = ?
                """,
                (project["project_id"], normalized_handoff_id),
            ).fetchone()
        if row is None:
            return None
        application = json.loads(row["application_json"])
        application["applied_at"] = row["applied_at"]
        return application

    def record_skill_plan_master_application(
        self,
        *,
        project_id: str,
        handoff: Mapping[str, Any],
        approval: Mapping[str, Any],
        delivery: Mapping[str, Any],
    ) -> tuple[dict[str, Any], bool]:
        project = self.get_project(project_id)
        source = handoff.get("source")
        if (
            not isinstance(source, Mapping)
            or source.get("kind") != "SKILL_PLAN"
            or handoff.get("project_id") != project["project_id"]
        ):
            raise UniverseError(
                "PROJECT_SKILL_PLAN_APPLICATION_INVALID",
                "handoff is not an adopted Skill Plan for this Project",
                HTTPStatus.CONFLICT,
            )
        adoption = source.get("adoption")
        if not isinstance(adoption, Mapping):
            raise UniverseError(
                "PROJECT_SKILL_PLAN_APPLICATION_INVALID",
                "handoff has no adopted Skill Plan payload",
                HTTPStatus.CONFLICT,
            )
        host_response = delivery.get("host_response")
        binding_proposal = (
            host_response.get("binding_proposal")
            if isinstance(host_response, Mapping)
            else None
        )
        if (
            not isinstance(host_response, Mapping)
            or host_response.get("status")
            != "PROJECT_SKILL_PLAN_BOUND_TO_MASTER_CONTEXT"
            or host_response.get("project_id") != project["project_id"]
            or host_response.get("handoff_id") != handoff.get("handoff_id")
            or host_response.get("adoption_id") != adoption.get("adoption_id")
            or not isinstance(binding_proposal, Mapping)
            or binding_proposal.get("status") != "PROJECT_SKILL_BINDING_PROPOSAL_READY"
            or binding_proposal.get("project_id") != project["project_id"]
            or binding_proposal.get("handoff_id") != handoff.get("handoff_id")
            or binding_proposal.get("adoption_id") != adoption.get("adoption_id")
            or binding_proposal.get("task_frame_started") is not False
        ):
            raise UniverseError(
                "PROJECT_SKILL_PLAN_APPLICATION_RECEIPT_INVALID",
                "Project Master did not return a matching Skill Plan receipt",
                HTTPStatus.CONFLICT,
            )
        approval_digest = _json_sha256(dict(approval))
        material = {
            "schema": PROJECT_SKILL_PLAN_MASTER_APPLICATION_SCHEMA,
            "project_id": project["project_id"],
            "handoff_id": handoff["handoff_id"],
            "handoff_digest": handoff["handoff_digest"],
            "adoption_id": adoption["adoption_id"],
            "selection_digest": adoption["selection_digest"],
            "approval_digest": approval_digest,
            "delivery": dict(delivery),
            "status": "PROJECT_SKILL_PLAN_BOUND_TO_MASTER_CONTEXT",
        }
        material["application_digest"] = _json_sha256(material)
        with self._connection() as connection:
            existing = connection.execute(
                """
                SELECT application_json, application_digest, applied_at
                FROM project_skill_plan_master_application
                WHERE handoff_id = ?
                """,
                (handoff["handoff_id"],),
            ).fetchone()
            if existing is not None:
                if existing["application_digest"] != material["application_digest"]:
                    raise UniverseError(
                        "PROJECT_SKILL_PLAN_APPLICATION_CONFLICT",
                        "handoff already has a different Master application",
                        HTTPStatus.CONFLICT,
                    )
                stored = json.loads(existing["application_json"])
                stored["applied_at"] = existing["applied_at"]
                return stored, False
            applied_at = utc_now()
            connection.execute(
                """
                INSERT INTO project_skill_plan_master_application(
                    handoff_id, project_id, adoption_id, approval_digest,
                    application_digest, application_json, applied_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    handoff["handoff_id"],
                    project["project_id"],
                    adoption["adoption_id"],
                    approval_digest,
                    material["application_digest"],
                    _canonical_json(material),
                    applied_at,
                ),
            )
        material["applied_at"] = applied_at
        return material, True

    def create_experience_case(
        self, project_id: str, value: Any
    ) -> tuple[dict[str, Any], bool]:
        project = self.get_project(project_id)
        request = normalize_experience_case_request(value)
        with self._connection() as connection:
            rows = connection.execute(
                """
                SELECT observation_id, project_id, candidate_id, candidate_digest, task_frame_ref,
                       source_ref, observation_digest, skill_binding_digest,
                       skill_id, skill_version, operation_class, context_pack_digest,
                       model_ref, provider_ref, worker_role, task_kind, node_ref,
                       failure_kind, quota_state, outcome, validation_state, evidence_refs_json,
                       metrics_json, observed_at, recorded_at
                FROM skill_run_observation
                WHERE project_id = ?
                  AND observation_id IN (SELECT value FROM json_each(?))
                """,
                (
                    project["project_id"],
                    _canonical_json(request["observation_ids"]),
                ),
            ).fetchall()
        observations_by_id = {
            row["observation_id"]: self._skill_observation_row(row) for row in rows
        }
        missing = sorted(set(request["observation_ids"]) - set(observations_by_id))
        if missing:
            raise UniverseError(
                "EXPERIENCE_CASE_OBSERVATION_NOT_FOUND",
                "observation_ids are not recorded for this Project: "
                + ", ".join(missing),
                HTTPStatus.CONFLICT,
            )
        observations = [
            observations_by_id[observation_id]
            for observation_id in request["observation_ids"]
        ]
        material: dict[str, Any] = {
            "schema": EXPERIENCE_CASE_SCHEMA,
            "project_id": project["project_id"],
            "observation_ids": request["observation_ids"],
            "observations": observations,
            "case_state": "OBSERVED",
            "causal_state": "NOT_INFERRED",
            "pattern_state": "NOT_EVALUATED",
            "effects": {
                "project_source_write": "NONE",
                "project_runtime_write": "NONE",
                "authority": "NONE",
                "execution_assignment": "NONE",
            },
            "next_operation": "USER_REVIEW_OR_EXPERIENCE_MATCH",
        }
        if "title" in request:
            material["title"] = request["title"]
        material["case_digest"] = _json_sha256(material)
        material["case_id"] = "case_" + material["case_digest"][:24]
        material["status"] = "EXPERIENCE_CASE_RECORDED"
        with self._connection() as connection:
            existing = connection.execute(
                """
                SELECT case_json, created_at
                FROM experience_case
                WHERE project_id = ? AND case_digest = ?
                """,
                (project["project_id"], material["case_digest"]),
            ).fetchone()
            if existing is not None:
                stored = json.loads(existing["case_json"])
                stored["created_at"] = existing["created_at"]
                return stored, False
            now = utc_now()
            connection.execute(
                """
                INSERT INTO experience_case(
                    case_id, project_id, case_digest, case_json, created_at
                ) VALUES (?, ?, ?, ?, ?)
                """,
                (
                    material["case_id"],
                    project["project_id"],
                    material["case_digest"],
                    _canonical_json(material),
                    now,
                ),
            )
            connection.executemany(
                """
                INSERT INTO experience_case_observation(case_id, observation_id)
                VALUES (?, ?)
                """,
                [
                    (material["case_id"], observation_id)
                    for observation_id in request["observation_ids"]
                ],
            )
        material["created_at"] = now
        return material, True

    def create_experience_cases_from_unlinked_observations(
        self, project_id: str, value: Any = None
    ) -> dict[str, Any]:
        """Create one Experience Case per observation not already in a case."""

        project = self.get_project(project_id)
        body = value if isinstance(value, dict) else {}
        limit = body.get("limit", 50)
        if (
            isinstance(limit, bool)
            or not isinstance(limit, int)
            or not 1 <= limit <= 200
        ):
            raise UniverseError(
                "EXPERIENCE_CASE_REQUEST_INVALID",
                "limit must be an integer from 1 through 200",
            )
        observations = self.list_skill_observations(project["project_id"], limit=500)
        linked_observation_ids: set[str] = set()
        with self._connection() as connection:
            rows = connection.execute(
                """
                SELECT observation_id
                FROM experience_case_observation
                WHERE case_id IN (
                    SELECT case_id FROM experience_case WHERE project_id = ?
                )
                """,
                (project["project_id"],),
            ).fetchall()
            linked_observation_ids = {row["observation_id"] for row in rows}
        created_cases: list[dict[str, Any]] = []
        reused_cases: list[dict[str, Any]] = []
        for observation in observations:
            observation_id = observation["observation_id"]
            if observation_id in linked_observation_ids:
                continue
            if len(created_cases) + len(reused_cases) >= limit:
                break
            skill = observation.get("skill") or {}
            title = f"Case for {skill.get('skill_id') or observation_id}"
            case, created = self.create_experience_case(
                project["project_id"],
                {
                    "observation_ids": [observation_id],
                    "title": title,
                },
            )
            if created:
                created_cases.append(case)
            else:
                reused_cases.append(case)
        return {
            "schema": "universe.experience-cases-from-observations.v1",
            "status": "EXPERIENCE_CASES_FROM_OBSERVATIONS_COMPLETED",
            "project_id": project["project_id"],
            "created_count": len(created_cases),
            "reused_count": len(reused_cases),
            "created": created_cases,
            "reused": reused_cases,
            "effects": {
                "project_source_write": "NONE",
                "authority": "NONE",
                "execution_assignment": "NONE",
                "causal_inference": "NONE",
            },
            "next_operation": "USER_REVIEW_OR_EXPERIENCE_MATCH",
        }

    def auto_experience_pattern_proposals(
        self, project_id: str, value: Any = None
    ) -> dict[str, Any]:
        """Attempt pattern proposals for each case with local match support."""

        project = self.get_project(project_id)
        body = value if isinstance(value, dict) else {}
        minimum_support = body.get("minimum_support", 2)
        if (
            isinstance(minimum_support, bool)
            or not isinstance(minimum_support, int)
            or not 2 <= minimum_support <= 20
        ):
            raise UniverseError(
                "EXPERIENCE_PATTERN_REQUEST_INVALID",
                "minimum_support must be an integer from 2 through 20",
            )
        cases = self.list_experience_cases(project["project_id"], limit=200)
        recorded: list[dict[str, Any]] = []
        skipped: list[dict[str, Any]] = []
        for case in cases:
            try:
                proposal, created = self.create_experience_pattern_proposal(
                    project["project_id"],
                    {
                        "case_id": case["case_id"],
                        "minimum_support": minimum_support,
                    },
                )
                recorded.append(
                    {
                        "case_id": case["case_id"],
                        "proposal_id": proposal.get("proposal_id"),
                        "created": created,
                        "support_case_count": proposal.get("support_case_count"),
                    }
                )
            except UniverseError as error:
                skipped.append(
                    {
                        "case_id": case["case_id"],
                        "error_code": error.code,
                        "message": error.message,
                    }
                )
        return {
            "schema": "universe.experience-pattern-auto.v1",
            "status": "EXPERIENCE_PATTERN_AUTO_COMPLETED",
            "project_id": project["project_id"],
            "recorded_count": len(recorded),
            "skipped_count": len(skipped),
            "recorded": recorded,
            "skipped": skipped,
            "effects": {
                "career_governance_write": "NONE",
                "promotion_state": "PROPOSAL_ONLY",
                "authority": "NONE",
            },
            "next_operation": "USER_REVIEW_OR_PATTERN_ADOPTION",
        }

    def list_experience_cases(
        self, project_id: str, *, limit: int = 100
    ) -> list[dict[str, Any]]:
        project = self.get_project(project_id)
        with self._connection() as connection:
            rows = connection.execute(
                """
                SELECT case_json, created_at
                FROM experience_case
                WHERE project_id = ?
                ORDER BY created_at DESC, case_id DESC
                LIMIT ?
                """,
                (project["project_id"], max(1, min(int(limit), 500))),
            ).fetchall()
        cases = []
        for row in rows:
            case = json.loads(row["case_json"])
            case["created_at"] = row["created_at"]
            cases.append(case)
        return cases

    def get_experience_case(self, project_id: str, case_id: str) -> dict[str, Any]:
        project = self.get_project(project_id)
        normalized_id = _identifier(case_id, "case_id")
        with self._connection() as connection:
            row = connection.execute(
                """
                SELECT case_json, created_at
                FROM experience_case
                WHERE project_id = ? AND case_id = ?
                """,
                (project["project_id"], normalized_id),
            ).fetchone()
        if row is None:
            raise UniverseError(
                "EXPERIENCE_CASE_NOT_FOUND",
                "Experience Case does not exist for this Project",
                HTTPStatus.NOT_FOUND,
            )
        case = json.loads(row["case_json"])
        case["created_at"] = row["created_at"]
        return case

    def match_experience_case(self, project_id: str, value: Any) -> dict[str, Any]:
        project = self.get_project(project_id)
        request = normalize_experience_match_request(value)
        subject = self.get_experience_case(project["project_id"], request["case_id"])
        candidates = [
            case
            for case in self.list_experience_cases(project["project_id"], limit=500)
            if case["case_id"] != subject["case_id"]
        ]
        subject_observations = subject["observations"]
        subject_bindings = {
            observation["skill_binding_digest"] for observation in subject_observations
        }
        subject_skills = {
            (
                observation["skill"]["skill_id"],
                observation["skill"]["skill_version"],
                observation["skill"]["operation_class"],
            )
            for observation in subject_observations
        }
        subject_outcomes = {
            observation["outcome"] for observation in subject_observations
        }
        subject_validation = {
            observation["validation_state"] for observation in subject_observations
        }
        matches = []
        for candidate in candidates:
            observations = candidate["observations"]
            bindings = {item["skill_binding_digest"] for item in observations}
            skills = {
                (
                    item["skill"]["skill_id"],
                    item["skill"]["skill_version"],
                    item["skill"]["operation_class"],
                )
                for item in observations
            }
            outcomes = {item["outcome"] for item in observations}
            validation_states = {item["validation_state"] for item in observations}
            shared_bindings = sorted(subject_bindings & bindings)
            shared_skills = sorted(subject_skills & skills)
            shared_outcomes = sorted(subject_outcomes & outcomes)
            shared_validation = sorted(subject_validation & validation_states)
            observed_dimension_count = sum(
                bool(value)
                for value in (
                    shared_bindings,
                    shared_skills,
                    shared_outcomes,
                    shared_validation,
                )
            )
            if not observed_dimension_count:
                continue
            matches.append(
                {
                    "case_id": candidate["case_id"],
                    "title": candidate.get("title"),
                    "relation": "OBSERVED_SIMILARITY",
                    "observed_dimension_count": observed_dimension_count,
                    "shared_skill_binding_digests": shared_bindings,
                    "shared_skills": [
                        {
                            "skill_id": skill_id,
                            "skill_version": skill_version,
                            "operation_class": operation_class,
                        }
                        for skill_id, skill_version, operation_class in shared_skills
                    ],
                    "shared_outcomes": shared_outcomes,
                    "shared_validation_states": shared_validation,
                    "causal_state": "NOT_INFERRED",
                    "pattern_state": "NOT_EVALUATED",
                }
            )
        matches.sort(
            key=lambda item: (
                -item["observed_dimension_count"],
                item["case_id"],
            )
        )
        return {
            "schema": "universe.experience-case-match.v1",
            "status": "EXPERIENCE_CASE_MATCHES_COLLECTED",
            "project_id": project["project_id"],
            "subject_case_id": subject["case_id"],
            "matches": matches[: request["limit"]],
            "match_scope": "PROJECT_LOCAL_OBSERVED_CASES",
            "effects": {
                "project_source_write": "NONE",
                "project_runtime_write": "NONE",
                "authority": "NONE",
                "execution_assignment": "NONE",
            },
            "next_operation": "USER_REVIEW_OR_PATTERN_PROPOSAL",
        }

    def create_experience_pattern_proposal(
        self, project_id: str, value: Any
    ) -> tuple[dict[str, Any], bool]:
        project = self.get_project(project_id)
        request = normalize_experience_pattern_proposal_request(value)
        subject = self.get_experience_case(project["project_id"], request["case_id"])
        match_result = self.match_experience_case(
            project["project_id"],
            {"case_id": subject["case_id"], "limit": 100},
        )
        supporting_ids = [subject["case_id"]] + [
            match["case_id"] for match in match_result["matches"]
        ]
        if len(supporting_ids) < request["minimum_support"]:
            raise UniverseError(
                "EXPERIENCE_PATTERN_INSUFFICIENT_SUPPORT",
                "not enough observed Cases share a supported similarity dimension",
                HTTPStatus.CONFLICT,
            )
        by_id = {
            case["case_id"]: case
            for case in self.list_experience_cases(project["project_id"], limit=500)
        }
        supporting_cases = [by_id[case_id] for case_id in supporting_ids]

        common_bindings = sorted(
            set.intersection(
                *[
                    {
                        observation["skill_binding_digest"]
                        for observation in case["observations"]
                    }
                    for case in supporting_cases
                ]
            )
        )
        common_outcomes = sorted(
            set.intersection(
                *[
                    {observation["outcome"] for observation in case["observations"]}
                    for case in supporting_cases
                ]
            )
        )
        common_validation_states = sorted(
            set.intersection(
                *[
                    {
                        observation["validation_state"]
                        for observation in case["observations"]
                    }
                    for case in supporting_cases
                ]
            )
        )
        skill_signatures = [
            {
                _canonical_json(
                    {
                        "skill_id": observation["skill"]["skill_id"],
                        "skill_version": observation["skill"]["skill_version"],
                        "operation_class": observation["skill"]["operation_class"],
                    }
                )
                for observation in case["observations"]
            }
            for case in supporting_cases
        ]
        common_skills = (
            set.intersection(*skill_signatures) if skill_signatures else set()
        )
        if not any(
            (common_bindings, common_skills, common_outcomes, common_validation_states)
        ):
            raise UniverseError(
                "EXPERIENCE_PATTERN_SIGNATURE_EMPTY",
                "supporting Cases do not have an exact observed signature in common",
                HTTPStatus.CONFLICT,
            )
        material = {
            "schema": EXPERIENCE_PATTERN_PROPOSAL_SCHEMA,
            "project_id": project["project_id"],
            "subject_case_id": subject["case_id"],
            "support_case_ids": sorted(supporting_ids),
            "support_case_count": len(supporting_ids),
            "observed_signature": {
                "skill_binding_digests": common_bindings,
                "skills": [
                    json.loads(signature) for signature in sorted(common_skills)
                ],
                "outcomes": common_outcomes,
                "validation_states": common_validation_states,
            },
            "causal_state": "NOT_INFERRED",
            "predictive_state": "NOT_EVALUATED",
            "promotion_state": "PROPOSAL_ONLY",
            "effects": {
                "career_governance_write": "NONE",
                "project_source_write": "NONE",
                "project_runtime_write": "NONE",
                "authority": "NONE",
                "execution_assignment": "NONE",
            },
            "next_operation": "USER_REVIEW_OR_PATTERN_ADOPTION",
        }
        material["proposal_digest"] = _json_sha256(material)
        material["proposal_id"] = "patternproposal_" + material["proposal_digest"][:24]
        material["status"] = "EXPERIENCE_PATTERN_PROPOSAL_READY"
        with self._connection() as connection:
            existing = connection.execute(
                """
                SELECT proposal_json, created_at
                FROM experience_pattern_proposal
                WHERE project_id = ? AND proposal_digest = ?
                """,
                (project["project_id"], material["proposal_digest"]),
            ).fetchone()
            if existing is not None:
                stored = json.loads(existing["proposal_json"])
                stored["created_at"] = existing["created_at"]
                return stored, False
            now = utc_now()
            connection.execute(
                """
                INSERT INTO experience_pattern_proposal(
                    proposal_id, project_id, proposal_digest, proposal_json, created_at
                ) VALUES (?, ?, ?, ?, ?)
                """,
                (
                    material["proposal_id"],
                    project["project_id"],
                    material["proposal_digest"],
                    _canonical_json(material),
                    now,
                ),
            )
        material["created_at"] = now
        return material, True

