            "/governance-proposals",
            "/provider-setting",
            "/room/stream",
            "/room/messages",
            "/document-incorporation-proposals",
            "/skill-plan-proposals",
            "/skill-plan-adoptions",
            "/master-handoffs",
            "/experience-cases/from-observations",
            "/experience-cases",
            "/work-loop/predictions/review",
            "/work-loop/review-candidates/review",
            "/work-loop/predictions",
            "/work-loop/recover",
            "/work-loop",
            "/semantic-graph",
            "/anchor-sessions",
            "/git-work-history",
            "/experience-matches",
            "/experience-patterns/auto",
            "/experience-pattern-proposals",
            "/memory-batches/run",
            "/memory-batches/runs",
            "/memory-batch-config",
            "/memory-candidates/review",
            "/memory-candidates",
            "/memories/propose-links",
            "/memories/maintain",
            "/memories/link",
            "/memories",
            "/career-promotion-queue",
            "/file-index/sync",
            "/file-index/search",
            "/file-index",
            "/retrieval-context",
            "/context-packs",
            "/release-proposals/apply",
            "/release-proposals",
            "/release-selection",
            "/runtime-worker-results",
            "/runtime-worker-invocations",
            "/dispatches",
            "/discovery-dispatch",
            "/projection",
            "/events",
            "/skill-observations",
            "/skill-gap-observations",
            "/skill-gap-summary",
            "/skill-candidates",
            "/skill-observation-queue",
            "/seed-asset-proposal/apply",
            "/seed-asset-proposal",
            "/seed",
            "/sync",
