    def _not_found(self) -> None:
        self._send(
            HTTPStatus.NOT_FOUND,
            {
                "schema": API_SCHEMA,
                "status": "NOT_FOUND",
                "error_code": "ROUTE_NOT_FOUND",
            },
        )

    def _send_provider_session_error(self, error: ProviderSessionError) -> None:
        try:
            status = HTTPStatus(int(error.status))
        except ValueError:
            status = HTTPStatus.CONFLICT
        self._send(
            status,
            {
                "schema": API_SCHEMA,
                "status": "ERROR",
                "error_code": error.code,
                "detail": error.detail,
            },
        )

    def _send_multi_room_error(self, error: MultiRoomError) -> None:
        self._send(
            HTTPStatus(error.status)
            if error.status in {400, 403, 404, 409}
            else HTTPStatus.BAD_REQUEST,
            {
                "schema": API_SCHEMA,
                "status": "ERROR",
                "error_code": error.code,
                "detail": error.detail,
            },
        )

    def _stream_multi_room(self, room_id: str) -> None:
        try:
            snapshot = self.server.multi_room_snapshot(room_id)
        except MultiRoomError as error:
            self._send_multi_room_error(error)
            return
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", "text/event-stream; charset=utf-8")
        self.send_header("Cache-Control", "no-cache")
        self.send_header("Connection", "close")
        self.end_headers()

        def write_event(event_name: str, payload: Mapping[str, Any]) -> None:
            body = json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
            chunk = f"event: {event_name}\ndata: {body}\n\n".encode("utf-8")
            self.wfile.write(chunk)
            self.wfile.flush()

        write_event(
            "snapshot",
            {
                "type": "SNAPSHOT",
                "room": snapshot["room"],
                "bindings": snapshot["bindings"],
                "messages": snapshot["messages"],
                "artifacts": snapshot["artifacts"],
                "findings": snapshot["findings"],
                "events": snapshot["events"],
                "participant_cursors": snapshot["participant_cursors"],
                "bridge_line": snapshot["bridge_line"],
                "permissions": snapshot["permissions"],
                "task_frame_timeline": snapshot.get("task_frame_timeline"),
            },
        )
        cursor = self.server.multi_rooms.hub.cursor()
        try:
            while True:
                events = self.server.multi_rooms.hub.wait(
                    room_id,
                    after_event_id=cursor,
                    timeout_seconds=15.0,
                )
                if not events:
                    room = snapshot.get("room")
                    if isinstance(room, Mapping) and room.get("room_type") == "BOSS":
                        write_event(
                            "task-frame",
                            self.server._task_frame_room_timeline(
                                str(room.get("task_frame_id") or ""),
                                str(room.get("project_id") or ""),
                            ),
                        )
                    else:
                        write_event("ping", {"type": "PING", "at": utc_now()})
                    continue
                for event in events:
                    cursor = max(cursor, int(event["event_id"]))
                    write_event("room", event)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            return

    def _stream_provider_session(self, chat_key: str) -> None:
        cursor = self.server.provider_sessions.events.cursor()
        self.server.hydrate_provider_session_transcript(chat_key)
        snapshot = self.server.provider_sessions.snapshot(chat_key)
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", "text/event-stream; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Connection", "keep-alive")
        self.send_header("X-Accel-Buffering", "no")
        self.end_headers()
        try:
            self._write_sse(
                cursor,
                {
                    "schema": PROVIDER_SESSION_STREAM_SCHEMA,
                    "event_id": cursor,
                    "chat_key": chat_key,
                    "emitted_at": utc_now(),
                    "payload": {"type": "SNAPSHOT", **snapshot},
                },
                event_name="provider-session",
            )
            while True:
                events = self.server.provider_sessions.events.wait(
                    chat_key,
                    after_event_id=cursor,
                    timeout_seconds=15.0,
                )
                if not events:
                    self.wfile.write(b": keepalive\n\n")
                    self.wfile.flush()
                    continue
                for event in events:
                    cursor = int(event["event_id"])
                    self._write_sse(
                        cursor,
                        event,
                        event_name="provider-session",
                    )
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            return

